    { const char * tb_v887 = "TB_API double exp(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v887; }
    { const char * tb_v888 = "    if (x > 709) return 1e308;\n"; *(const char * *)tb_grow(v_lines) = tb_v888; }
