    { const char * tb_v897 = "TB_API double log(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v897; }
    { const char * tb_v898 = "    if (x <= 0) return -1e308;\n"; *(const char * *)tb_grow(v_lines) = tb_v898; }
