    { const char * tb_v1502 = "TB_API void tb_map_2m(uint64_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1502; }
    { const char * tb_v1503 = "    if (a >= (4ull << 30) || a < (uint64_t)(uintptr_t)tb_heap_area) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v1503; }
    { const char * tb_v1504 = "    uint64_t *e = &tb_pdir[a >> 30][(a >> 21) & 511];\n"; *(const char * *)tb_grow(v_lines) = tb_v1504; }
