    { const char * tb_v1509 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1509; }
    { const char * tb_v1510 = "TB_API int tb_find_cpus(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1510; }
    { const char * tb_v1511 = "    unsigned char *rsdp = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1511; }
    { const char * tb_v1512 = "    for (uint64_t a = 0xE0000; a < 0x100000 && !rsdp; a += 16)\n"; *(const char * *)tb_grow(v_lines) = tb_v1512; }
    { const char * tb_v1513 = "        if (memcmp((void *)(uintptr_t)a, \"RSD PTR \", 8) == 0) rsdp = (unsigned char *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v1513; }
    { const char * tb_v1514 = "    if (!rsdp) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1514; }
    { const char * tb_v1515 = "    unsigned char *rsdt = (unsigned char *)(uintptr_t)*(uint32_t *)(rsdp + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v1515; }
    { const char * tb_v1516 = "    tb_map_2m((uint64_t)(uintptr_t)rsdt);\n"; *(const char * *)tb_grow(v_lines) = tb_v1516; }
    { const char * tb_v1517 = "    uint32_t len = *(uint32_t *)(rsdt + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v1517; }
    { const char * tb_v1518 = "    int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1518; }
    { const char * tb_v1519 = "    for (uint32_t o = 36; o + 4 <= len; o += 4) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1519; }
