    { const char * tb_v1523 = "        uint32_t tl = *(uint32_t *)(t + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v1523; }
    { const char * tb_v1524 = "        for (uint32_t e = 44; e + 2 <= tl && n < TB_NCPU; e += t[e + 1]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1524; }
