    { const char * tb_v1535 = "__asm__(\".text\\n.global tb_tramp\\n.global tb_tramp_end\\n.global tb_tr_cr3\\n.global tb_tr_stack\\n.code16\\ntb_tramp:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1535; }
    { const char * tb_v1536 = "        \"  cli\\n  xorw %ax, %ax\\n  movw %ax, %ds\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1536; }
