    { const char * tb_v1779 = "// как в POSIX: файл на месте назначения заменяется (обычный rename на Windows так не умеет)\n"; *(const char * *)tb_grow(v_lines) = tb_v1779; }
    { const char * tb_v1780 = "TB_API int tb_win_rename(const char *from, const char *to) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1780; }
