    { const char * tb_v1789 = "// getenv в UTF-8; ответ живёт до конца программы (их мало и они короткие).\n"; *(const char * *)tb_grow(v_lines) = tb_v1789; }
    { const char * tb_v1790 = "// HOME на Windows обычно нет: тогда это USERPROFILE (C:\\Users\\имя)\n"; *(const char * *)tb_grow(v_lines) = tb_v1790; }
