    { const char * tb_v1924 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1924; }
    { const char * tb_v1925 = "// у каждого потока своё: где начинается его стек и сколько в нём места\n"; *(const char * *)tb_grow(v_lines) = tb_v1925; }
