    { const char * tb_v2202 = "TB_API long long tb_gsince = 0, tb_glive = 0, tb_gnext = 8LL << 20, tb_gstress = 0, tb_gcount = 0, tb_gruns = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2202; }
    { const char * tb_v2203 = "TB_API int tb_gready = 0, tb_goff = 0, tb_gstats = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2203; }
    { const char * tb_v2204 = "TB_API char *tb_gtop = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2204; }
    { const char * tb_v2205 = "TB_API pthread_mutex_t tb_glock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2205; }
