    { const char * tb_v2223 = "    tb_gpage ***d = &tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v2223; }
    { const char * tb_v2224 = "    if (!*d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2224; }
    { const char * tb_v2225 = "        *d = calloc(1 << 16, sizeof(tb_gpage *));\n"; *(const char * *)tb_grow(v_lines) = tb_v2225; }
