    { const char * tb_v2868 = "TB_API long long tb_ulen(const char *s) { return tb_u8info(s, -1)->nl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2868; }
    { const char * tb_v2869 = "TB_API long long tb_ulen_n(const char *s, long long nb) { return nb < 0 ? tb_ulen(s) : tb_u8info(s, nb)->nl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2869; }
    { const char * tb_v2870 = "// байт, с которого начинается буква i (i == букв — конец текста)\n"; *(const char * *)tb_grow(v_lines) = tb_v2870; }
    { const char * tb_v2871 = "TB_API long long tb_u8off(tb_u8slot *c, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2871; }
