    { const char * tb_v2886 = "// буквы из двух байт (русские, греческие...): готовые строки, как tb_chars для латиницы\n"; *(const char * *)tb_grow(v_lines) = tb_v2886; }
    { const char * tb_v2887 = "TB_API char tb_chars2[2048 * 4];\n"; *(const char * *)tb_grow(v_lines) = tb_v2887; }
    { const char * tb_v2888 = "TB_API const char *tb_u8text(const char *p, long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2888; }
    { const char * tb_v2889 = "    if (n == 1) return tb_chr((unsigned char)p[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v2889; }
    { const char * tb_v2890 = "    if (n == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2890; }
    { const char * tb_v2891 = "        unsigned cp = (((unsigned char)p[0] & 0x1F) << 6) | ((unsigned char)p[1] & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v2891; }
