    { const char * tb_v2893 = "        if (!t[0]) { t[1] = p[1]; t[2] = 0; __atomic_store_n(&t[0], p[0], __ATOMIC_RELEASE); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2893; }
