    { const char * tb_v2909 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2909; }
    { const char * tb_v2910 = "// each ch in s: буква с байта *i; *i становится последним байтом буквы (цикл сам прибавит 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2910; }
    { const char * tb_v2911 = "TB_API const char *tb_u8take(const char *s, long long *i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2911; }
