    { const char * tb_v2948 = "TB_API void tb_app_n(const char **p, long long *rl, long long *rc, const char *b, long long lb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2948; }
    { const char * tb_v2949 = "    char *s = (char *)*p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2949; }
    { const char * tb_v2950 = "    if (*rl < 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2950; }
    { const char * tb_v2951 = "        long long la = (long long)strlen(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v2951; }
    { const char * tb_v2952 = "        long long cap = 2 * (la + lb) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2952; }
    { const char * tb_v2953 = "        if (cap < 64) cap = 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v2953; }
    { const char * tb_v2954 = "        char *r = tb_tmem(cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v2954; }
    { const char * tb_v2955 = "        memcpy(r, s, la);\n"; *(const char * *)tb_grow(v_lines) = tb_v2955; }
