    { const char * tb_v2957 = "        r[la + lb] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2957; }
    { const char * tb_v2958 = "        *p = r; *rl = la + lb; *rc = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2958; }
    { const char * tb_v2959 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2959; }
    { const char * tb_v2960 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2960; }
    { const char * tb_v2961 = "    long long need = *rl + lb + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2961; }
    { const char * tb_v2962 = "    if (need > *rc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2962; }
    { const char * tb_v2963 = "        long long cap = 2 * need;\n"; *(const char * *)tb_grow(v_lines) = tb_v2963; }
    { const char * tb_v2964 = "        long long off = (b >= s && b < s + *rc) ? b - s : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2964; }
