    { const char * tb_v2974 = "    tb_u8slot *c = tb_u8info(s, -1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2974; }
    { const char * tb_v2975 = "    if (from < 0 || to >= c->nl || from > to + 1) tb_crash(line, \"cut: номера за пределами текста\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2975; }
    { const char * tb_v2976 = "    long long a = tb_u8off(c, from), b = tb_u8off(c, to + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2976; }
