    { const char * tb_v3264 = "    // адрес — в одинарных кавычках для shell: ' внутри адреса пишется как '\\''\n"; *(const char * *)tb_grow(v_lines) = tb_v3264; }
    { const char * tb_v3265 = "    size_t n = strlen(url);\n"; *(const char * *)tb_grow(v_lines) = tb_v3265; }
