    { const char * tb_v3624 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3624; }
    { const char * tb_v3625 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v3625; }
    { const char * tb_v3626 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v3626; }
    { const char * tb_v3627 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v3627; }
    { const char * tb_v3628 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v3628; }
    { const char * tb_v3629 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3629; }
    { const char * tb_v3630 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v3630; }
