    { const char * tb_v3634 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3634; }
    { const char * tb_v3635 = "// список целиком: сам список, его память и (texts) тексты-элементы\n"; *(const char * *)tb_grow(v_lines) = tb_v3635; }
    { const char * tb_v3636 = "TB_API void tb_export_list(tb_list *l, int texts) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3636; }
    { const char * tb_v3637 = "    if (!l) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3637; }
