    { const char * tb_v3674 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3674; }
    { const char * tb_v3675 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3675; }
