    { const char * tb_v3678 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3678; }
    { const char * tb_v3679 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3679; }
    { const char * tb_v3680 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v3680; }
    { const char * tb_v3681 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3681; }
    { const char * tb_v3682 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3682; }
    { const char * tb_v3683 = "        // метка хеша совпала — только тогда сравниваем сами ключи (текст — дорого)\n"; *(const char * *)tb_grow(v_lines) = tb_v3683; }
    { const char * tb_v3684 = "        if ((sl & ~TB_DAT) == tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3684; }
    { const char * tb_v3685 = "            long long at = (sl & TB_DAT) - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3685; }
    { const char * tb_v3686 = "            if (tb_keq(d, d->keys->data + at * d->keys->size, k)) return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v3686; }
    { const char * tb_v3687 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3687; }
