    { const char * tb_v3689 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3689; }
    { const char * tb_v3690 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3690; }
    { const char * tb_v3691 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3691; }
    { const char * tb_v3692 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v3692; }
