    { const char * tb_v3702 = "        if (!(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v3702; }
    { const char * tb_v3703 = "        d->pos = 0; d->npos = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3703; }
    { const char * tb_v3704 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3704; }
    { const char * tb_v3705 = "    d->nslots = nslots;\n"; *(const char * *)tb_grow(v_lines) = tb_v3705; }
    { const char * tb_v3706 = "    d->slots = tb_dalloc(d, d->slots, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v3706; }
    { const char * tb_v3707 = "    memset(d->slots, 0, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v3707; }
    { const char * tb_v3708 = "    unsigned long long mask = nslots - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3708; }
    { const char * tb_v3709 = "    for (long long at = 0; at < d->keys->len; at++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3709; }
    { const char * tb_v3710 = "        unsigned long long h = tb_hash(d, d->keys->data + at * d->keys->size), i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3710; }
    { const char * tb_v3711 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3711; }
