    { const char * tb_v3715 = "// перейти на таблицу с хешем (ключ ушёл далеко от остальных или его удалили)\n"; *(const char * *)tb_grow(v_lines) = tb_v3715; }
    { const char * tb_v3716 = "TB_API void tb_dto_hash(tb_dict *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3716; }
    { const char * tb_v3717 = "    long long n = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v3717; }
