    { const char * tb_v3740 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3740; }
    { const char * tb_v3741 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3741; }
    { const char * tb_v3742 = "// .clear(): список снова пустой; свой кусок памяти отдаётся (если он не временный).\n"; *(const char * *)tb_grow(v_lines) = tb_v3742; }
    { const char * tb_v3743 = "// Тексты и obj внутри не удаляются: на них могут смотреть другие переменные.\n"; *(const char * *)tb_grow(v_lines) = tb_v3743; }
    { const char * tb_v3744 = "TB_API void tb_lclear(tb_list *l, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3744; }
    { const char * tb_v3745 = "    if (l->cap < 0) tb_crash(line, \".clear() нельзя, пока по списку идёт each ... by N\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3745; }
    { const char * tb_v3746 = "    int temp = tb_nchunks > 0 && tb_in_temp(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v3746; }
