    { const char * tb_v3751 = "    if (l->data == 0) tb_crash(line, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3751; }
    { const char * tb_v3752 = "    memset(l->data, 0, bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v3752; }
    { const char * tb_v3753 = "    l->len = 0; l->cap = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v3753; }
    { const char * tb_v3754 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3754; }
    { const char * tb_v3755 = "// --llvm: число ключей (из .ll не надо знать устройство tb_dict)\n"; *(const char * *)tb_grow(v_lines) = tb_v3755; }
    { const char * tb_v3756 = "TB_INL long long tb_dlen(tb_dict *d) { return d->keys->len; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3756; }
    { const char * tb_v3757 = "TB_INL tb_list *tb_dkeys_copy(tb_dict *d) { return tb_copy(d->keys); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3757; }
    { const char * tb_v3758 = "TB_INL tb_list *tb_dvals_copy(tb_dict *d) { return tb_copy(d->vals); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3758; }
    { const char * tb_v3759 = "TB_API void tb_dclear(tb_dict *d, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3759; }
    { const char * tb_v3760 = "    tb_lclear(d->keys, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3760; }
