    { const char * tb_v3762 = "    if (d->pos && !(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v3762; }
    { const char * tb_v3763 = "    if (d->slots && !(tb_nchunks > 0 && tb_in_temp(d->slots))) tb_gc_free(d->slots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3763; }
    { const char * tb_v3764 = "    d->slots = 0; d->pos = 0; d->npos = 0; d->base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3764; }
    { const char * tb_v3765 = "    if (d->text) tb_dreindex(d, 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v3765; }
    { const char * tb_v3766 = "    else { d->mode = 1; d->nslots = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3766; }
    { const char * tb_v3767 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3767; }
    { const char * tb_v3768 = "// новый ключ int k: можно ли остаться без поиска (mode 1 или 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v3768; }
    { const char * tb_v3769 = "TB_API void tb_dplace_int(tb_dict *d, long long k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3769; }
    { const char * tb_v3770 = "    long long n = d->keys->len;          // уже вместе с новым ключом\n"; *(const char * *)tb_grow(v_lines) = tb_v3770; }
    { const char * tb_v3771 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3771; }
    { const char * tb_v3772 = "        if (n == 1) { d->base = k; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3772; }
    { const char * tb_v3773 = "        if (k == d->base + n - 1) return;  // подряд — остаёмся в mode 1\n"; *(const char * *)tb_grow(v_lines) = tb_v3773; }
    { const char * tb_v3774 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3774; }
    { const char * tb_v3775 = "    if (d->mode == 1 || d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3775; }
    { const char * tb_v3776 = "        // плотно ли: ключи не дальше 4 ячеек на один ключ\n"; *(const char * *)tb_grow(v_lines) = tb_v3776; }
