    { const char * tb_v3779 = "            if (d->mode == 2 && o < d->npos) { d->pos[o] = n; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3779; }
    { const char * tb_v3780 = "            long long want = d->npos * 2 > o + 1 ? d->npos * 2 : o + 1 + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3780; }
    { const char * tb_v3781 = "            if (want < 16) want = 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v3781; }
    { const char * tb_v3782 = "            tb_dto_pos(d, want);\n"; *(const char * *)tb_grow(v_lines) = tb_v3782; }
    { const char * tb_v3783 = "            return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3783; }
    { const char * tb_v3784 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3784; }
    { const char * tb_v3785 = "        tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3785; }
    { const char * tb_v3786 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3786; }
    { const char * tb_v3787 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3787; }
    { const char * tb_v3788 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3788; }
    { const char * tb_v3789 = "// место под значение ключа k; если ключа нет — добавить со значением *def\n"; *(const char * *)tb_grow(v_lines) = tb_v3789; }
    { const char * tb_v3790 = "TB_API void *tb_dput(tb_dict *d, const void *k, const void *def) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3790; }
    { const char * tb_v3791 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3791; }
    { const char * tb_v3792 = "    if (at >= 0) return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3792; }
    { const char * tb_v3793 = "    memcpy(tb_grow(d->keys), k, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3793; }
    { const char * tb_v3794 = "    void *v = tb_grow(d->vals);\n"; *(const char * *)tb_grow(v_lines) = tb_v3794; }
    { const char * tb_v3795 = "    if (def) memcpy(v, def, d->vals->size); else memset(v, 0, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3795; }
    { const char * tb_v3796 = "    if (d->mode != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3796; }
    { const char * tb_v3797 = "        // без поиска; если ключ лёг далеко, tb_dplace_int сам перейдёт на хеш и впишет все ключи\n"; *(const char * *)tb_grow(v_lines) = tb_v3797; }
    { const char * tb_v3798 = "        tb_dplace_int(d, *(const long long *)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3798; }
    { const char * tb_v3799 = "        return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3799; }
    { const char * tb_v3800 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3800; }
    { const char * tb_v3801 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v3801; }
    { const char * tb_v3802 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3802; }
    { const char * tb_v3803 = "        unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3803; }
    { const char * tb_v3804 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3804; }
    { const char * tb_v3805 = "        d->slots[i] = d->keys->len | TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v3805; }
    { const char * tb_v3806 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3806; }
    { const char * tb_v3807 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3807; }
    { const char * tb_v3808 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3808; }
    { const char * tb_v3809 = "TB_API void *tb_dget(tb_dict *d, const void *k, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3809; }
    { const char * tb_v3810 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3810; }
    { const char * tb_v3811 = "    if (TB_RARE(at < 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3811; }
    { const char * tb_v3812 = "        if (d->text) tb_crash(line, tb_cat(\"в dict нет ключа: \", *(const char * const *)k));\n"; *(const char * *)tb_grow(v_lines) = tb_v3812; }
    { const char * tb_v3813 = "        tb_crash(line, tb_cat(\"в dict нет ключа: \", tb_itos(*(const long long *)k)));\n"; *(const char * *)tb_grow(v_lines) = tb_v3813; }
    { const char * tb_v3814 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3814; }
    { const char * tb_v3815 = "    return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3815; }
    { const char * tb_v3816 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3816; }
    { const char * tb_v3817 = "// together: шаг 1 — просим память принести место ключа заранее\n"; *(const char * *)tb_grow(v_lines) = tb_v3817; }
    { const char * tb_v3818 = "TB_INL unsigned long long tb_dpre1(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3818; }
    { const char * tb_v3819 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3819; }
    { const char * tb_v3820 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v3820; }
    { const char * tb_v3821 = "        if (at < (unsigned long long)d->vals->len) __builtin_prefetch(d->vals->data + at * d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3821; }
    { const char * tb_v3822 = "        return ~0ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3822; }
    { const char * tb_v3823 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3823; }
    { const char * tb_v3824 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3824; }
    { const char * tb_v3825 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v3825; }
    { const char * tb_v3826 = "        if (o < (unsigned long long)d->npos) { __builtin_prefetch(&d->pos[o]); return o; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3826; }
    { const char * tb_v3827 = "        return ~0ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3827; }
    { const char * tb_v3828 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3828; }
    { const char * tb_v3829 = "    unsigned long long i = tb_hash(d, k) & (d->nslots - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3829; }
    { const char * tb_v3830 = "    __builtin_prefetch(&d->slots[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v3830; }
    { const char * tb_v3831 = "    return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v3831; }
    { const char * tb_v3832 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3832; }
    { const char * tb_v3833 = "// шаг 2 — место приехало: просим принести ключ и значение\n"; *(const char * *)tb_grow(v_lines) = tb_v3833; }
    { const char * tb_v3834 = "TB_INL void tb_dpre2(tb_dict *d, unsigned long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3834; }
    { const char * tb_v3835 = "    if (i == ~0ULL || d->mode == 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3835; }
    { const char * tb_v3836 = "    long long s = d->mode == 2 ? d->pos[i] : (d->slots[i] & TB_DAT);\n"; *(const char * *)tb_grow(v_lines) = tb_v3836; }
    { const char * tb_v3837 = "    if (s != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3837; }
    { const char * tb_v3838 = "        if (d->mode == 0) __builtin_prefetch(d->keys->data + (s - 1) * d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3838; }
    { const char * tb_v3839 = "        __builtin_prefetch(d->vals->data + (s - 1) * d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3839; }
    { const char * tb_v3840 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3840; }
    { const char * tb_v3841 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3841; }
    { const char * tb_v3842 = "// элемент списка заранее (prefetch за пределами списка ничего не ломает)\n"; *(const char * *)tb_grow(v_lines) = tb_v3842; }
    { const char * tb_v3843 = "TB_INL void tb_lpre(tb_list *l, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3843; }
    { const char * tb_v3844 = "    __builtin_prefetch(l->data + i * l->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3844; }
    { const char * tb_v3845 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3845; }
    { const char * tb_v3846 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3846; }
    { const char * tb_v3847 = "TB_API void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3847; }
    { const char * tb_v3848 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3848; }
    { const char * tb_v3849 = "    void *r = tb_gc_alloc(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3849; }
