    { const char * tb_v3852 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3852; }
    { const char * tb_v3853 = "TB_API void *tb_cold_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3853; }
    { const char * tb_v3854 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3854; }
    { const char * tb_v3855 = "    void *r = tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3855; }
    { const char * tb_v3856 = "    memset(r, 0, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3856; }
    { const char * tb_v3857 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3857; }
    { const char * tb_v3858 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3858; }
    { const char * tb_v3859 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3859; }
    { const char * tb_v3860 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v3860; }
    { const char * tb_v3861 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3861; }
