    { const char * tb_v3868 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3868; }
    { const char * tb_v3869 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3869; }
    { const char * tb_v3870 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3870; }
    { const char * tb_v3871 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v3871; }
    { const char * tb_v3872 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3872; }
    { const char * tb_v3873 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3873; }
    { const char * tb_v3874 = "    if (tb_thread_create(&t->th, run, arg) != 0) tb_crash(0, \"не получилось запустить background\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3874; }
    { const char * tb_v3875 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3875; }
    { const char * tb_v3876 = "// a = service f(): в программе с ОС служба — тот же background (запас памяти есть только в ядре)\n"; *(const char * *)tb_grow(v_lines) = tb_v3876; }
    { const char * tb_v3877 = "TB_API void tb_service_start(tb_task *t, void *(*run)(void *), void *arg) { tb_task_start(t, run, arg); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3877; }
    { const char * tb_v3878 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v3878; }
    { const char * tb_v3879 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3879; }
    { const char * tb_v3880 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3880; }
    { const char * tb_v3881 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v3881; }
    { const char * tb_v3882 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3882; }
    { const char * tb_v3883 = "// a.crashed: в обычной программе падение задачи роняет всю программу — сюда доходят только целые\n"; *(const char * *)tb_grow(v_lines) = tb_v3883; }
    { const char * tb_v3884 = "TB_API _Bool tb_crashed(tb_task *t) { tb_wait(t); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3884; }
    { const char * tb_v3885 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3885; }
    { const char * tb_v3886 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3886; }
    { const char * tb_v3887 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3887; }
    { const char * tb_v3888 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3888; }
    { const char * tb_v3889 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3889; }
    { const char * tb_v3890 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3890; }
    { const char * tb_v3891 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3891; }
    { const char * tb_v3892 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v3892; }
    { const char * tb_v3893 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3893; }
    { const char * tb_v3894 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3894; }
    { const char * tb_v3895 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3895; }
    { const char * tb_v3896 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3896; }
    { const char * tb_v3897 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3897; }
    { const char * tb_v3898 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3898; }
    { const char * tb_v3899 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3899; }
    { const char * tb_v3900 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3900; }
    { const char * tb_v3901 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3901; }
    { const char * tb_v3902 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3902; }
    { const char * tb_v3903 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3903; }
    { const char * tb_v3904 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3904; }
    { const char * tb_v3905 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3905; }
    { const char * tb_v3906 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3906; }
    { const char * tb_v3907 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3907; }
    { const char * tb_v3908 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3908; }
    { const char * tb_v3909 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v3909; }
    { const char * tb_v3910 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v3910; }
    { const char * tb_v3911 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v3911; }
    { const char * tb_v3912 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3912; }
    { const char * tb_v3913 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3913; }
    { const char * tb_v3914 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v3914; }
    { const char * tb_v3915 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v3915; }
    { const char * tb_v3916 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3916; }
    { const char * tb_v3917 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3917; }
    { const char * tb_v3918 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3918; }
    { const char * tb_v3919 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3919; }
    { const char * tb_v3920 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3920; }
    { const char * tb_v3921 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3921; }
    { const char * tb_v3922 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3922; }
    { const char * tb_v3923 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3923; }
    { const char * tb_v3924 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3924; }
    { const char * tb_v3925 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3925; }
    { const char * tb_v3926 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3926; }
    { const char * tb_v3927 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3927; }
    { const char * tb_v3928 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3928; }
    { const char * tb_v3929 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3929; }
    { const char * tb_v3930 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v3930; }
    { const char * tb_v3931 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v3931; }
    { const char * tb_v3932 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3932; }
    { const char * tb_v3933 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3933; }
    { const char * tb_v3934 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3934; }
    { const char * tb_v3935 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3935; }
    { const char * tb_v3936 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3936; }
    { const char * tb_v3937 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3937; }
    { const char * tb_v3938 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3938; }
    { const char * tb_v3939 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3939; }
    { const char * tb_v3940 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v3940; }
    { const char * tb_v3941 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v3941; }
    { const char * tb_v3942 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3942; }
    { const char * tb_v3943 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3943; }
    { const char * tb_v3944 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3944; }
    { const char * tb_v3945 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v3945; }
    { const char * tb_v3946 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3946; }
    { const char * tb_v3947 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3947; }
    { const char * tb_v3948 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3948; }
    { const char * tb_v3949 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3949; }
    { const char * tb_v3950 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v3950; }
    { const char * tb_v3951 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v3951; }
    { const char * tb_v3952 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v3952; }
    { const char * tb_v3953 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v3953; }
    { const char * tb_v3954 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3954; }
    { const char * tb_v3955 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3955; }
    { const char * tb_v3956 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3956; }
    { const char * tb_v3957 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3957; }
    { const char * tb_v3958 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3958; }
    { const char * tb_v3959 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3959; }
    { const char * tb_v3960 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v3960; }
    { const char * tb_v3961 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3961; }
    { const char * tb_v3962 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3962; }
    { const char * tb_v3963 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3963; }
    { const char * tb_v3964 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3964; }
    { const char * tb_v3965 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3965; }
    { const char * tb_v3966 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3966; }
    { const char * tb_v3967 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3967; }
    { const char * tb_v3968 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3968; }
    { const char * tb_v3969 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3969; }
    { const char * tb_v3970 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3970; }
    { const char * tb_v3971 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v3971; }
    { const char * tb_v3972 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3972; }
    { const char * tb_v3973 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3973; }
    { const char * tb_v3974 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3974; }
    { const char * tb_v3975 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3975; }
    { const char * tb_v3976 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3976; }
    { const char * tb_v3977 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3977; }
    { const char * tb_v3978 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3978; }
    { const char * tb_v3979 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3979; }
    { const char * tb_v3980 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3980; }
    { const char * tb_v3981 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v3981; }
    { const char * tb_v3982 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3982; }
    { const char * tb_v3983 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v3983; }
    { const char * tb_v3984 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3984; }
    { const char * tb_v3985 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3985; }
    { const char * tb_v3986 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3986; }
    { const char * tb_v3987 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3987; }
    { const char * tb_v3988 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3988; }
    { const char * tb_v3989 = "    __atomic_add_fetch(&tb_gthreads, n - 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v3989; }
    { const char * tb_v3990 = "    __atomic_add_fetch(&tb_pool_gen, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3990; }
    { const char * tb_v3991 = "    pthread_cond_broadcast(&tb_pool_go);\n"; *(const char * *)tb_grow(v_lines) = tb_v3991; }
    { const char * tb_v3992 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3992; }
    { const char * tb_v3993 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3993; }
    { const char * tb_v3994 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3994; }
    { const char * tb_v3995 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3995; }
    { const char * tb_v3996 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3996; }
    { const char * tb_v3997 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3997; }
    { const char * tb_v3998 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3998; }
    { const char * tb_v3999 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3999; }
    { const char * tb_v4000 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4000; }
    { const char * tb_v4001 = "    __atomic_store_n(&tb_pool_busy, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v4001; }
    { const char * tb_v4002 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4002; }
    { const char * tb_v4003 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4003; }
    { const char * tb_v4004 = "TB_API long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4004; }
    { const char * tb_v4005 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v4005; }
    { const char * tb_v4006 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4006; }
    { const char * tb_v4007 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4007; }
    { const char * tb_v4008 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v4008; }
    { const char * tb_v4009 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4009; }
    { const char * tb_v4010 = "TB_INL long long tb_band(long long a, long long b) { return a & b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4010; }
    { const char * tb_v4011 = "TB_INL long long tb_bor(long long a, long long b) { return a | b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4011; }
    { const char * tb_v4012 = "TB_INL long long tb_bxor(long long a, long long b) { return a ^ b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4012; }
    { const char * tb_v4013 = "TB_INL long long tb_bnot(long long a) { return ~a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4013; }
    { const char * tb_v4014 = "TB_INL long long tb_shl(long long a, long long n) { return (long long)((unsigned long long)a << (n & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4014; }
    { const char * tb_v4015 = "TB_INL long long tb_shr(long long a, long long n) { return (long long)((unsigned long long)a >> (n & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4015; }
    { const char * tb_v4016 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v4016; }
    { const char * tb_v4017 = "// shared x += n без замка. В ядре без ОС одно ядро процессора: хватает выключить прерывания\n"; *(const char * *)tb_grow(v_lines) = tb_v4017; }
    { const char * tb_v4018 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4018; }
    { const char * tb_v4019 = "static inline void tb_atomic_addi(volatile long long *p, long long v) { uint64_t f = tb_irq_save(); *p += v; tb_irq_restore(f); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4019; }
    { const char * tb_v4020 = "static inline void tb_atomic_addd(volatile double *p, double v) { uint64_t f = tb_irq_save(); *p += v; tb_irq_restore(f); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4020; }
    { const char * tb_v4021 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4021; }
    { const char * tb_v4022 = "static inline void tb_atomic_addi(volatile long long *p, long long v) { __atomic_fetch_add(p, v, __ATOMIC_SEQ_CST); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4022; }
    { const char * tb_v4023 = "// дробь: сравнить и заменить, пока никто не успел поменять\n"; *(const char * *)tb_grow(v_lines) = tb_v4023; }
    { const char * tb_v4024 = "static inline void tb_atomic_addd(volatile double *p, double v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4024; }
