    { const char * tb_v4033 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v4033; }
    { const char * tb_v4034 = "// ---------- память руками: new_mem, free_mem, grow_mem, copy_mem, fill_mem (только в danger) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4034; }
    { const char * tb_v4035 = "// Перед каждым блоком 16 байт: размер и метка «живой» / «освобождён» — так free_mem ловит чужой\n"; *(const char * *)tb_grow(v_lines) = tb_v4035; }
    { const char * tb_v4036 = "// адрес и второе освобождение. TB_MEM_CHECK=1 (не в ядре): за блоком 16 байт-сторожей, освобождённые\n"; *(const char * *)tb_grow(v_lines) = tb_v4036; }
    { const char * tb_v4037 = "// блоки не отдаются обратно (их чтение и запись ловятся), read/write/copy_mem/fill_mem проверяют\n"; *(const char * *)tb_grow(v_lines) = tb_v4037; }
    { const char * tb_v4038 = "// адрес, а в конце программы печатается, что не освобождено\n"; *(const char * *)tb_grow(v_lines) = tb_v4038; }
    { const char * tb_v4039 = "#define TB_MEM_LIVE 0x4D454D4C49564521ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v4039; }
    { const char * tb_v4040 = "#define TB_MEM_DEAD 0x4D454D4445414421ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v4040; }
    { const char * tb_v4041 = "#define TB_MEM_GUARD 16\n"; *(const char * *)tb_grow(v_lines) = tb_v4041; }
    { const char * tb_v4042 = "typedef struct { uint64_t size, magic; } tb_memh;\n"; *(const char * *)tb_grow(v_lines) = tb_v4042; }
    { const char * tb_v4043 = "typedef struct { uintptr_t a; uint64_t n; int live, line, fline; } tb_memb;\n"; *(const char * *)tb_grow(v_lines) = tb_v4043; }
    { const char * tb_v4044 = "TB_API int tb_mem_check = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4044; }
    { const char * tb_v4045 = "TB_API tb_memb *tb_mem_all = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4045; }
    { const char * tb_v4046 = "TB_API long long tb_mem_n = 0, tb_mem_cap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4046; }
    { const char * tb_v4047 = "TB_API volatile int tb_mem_spin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4047; }
    { const char * tb_v4048 = "TB_API void tb_mem_report(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v4048; }
    { const char * tb_v4049 = "TB_INL int tb_memchk(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4049; }
    { const char * tb_v4050 = "    if (TB_RARE(tb_mem_check < 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4050; }
    { const char * tb_v4051 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4051; }
    { const char * tb_v4052 = "        tb_mem_check = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4052; }
    { const char * tb_v4053 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4053; }
    { const char * tb_v4054 = "        const char *e = getenv(\"TB_MEM_CHECK\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4054; }
    { const char * tb_v4055 = "        tb_mem_check = e && e[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v4055; }
    { const char * tb_v4056 = "        if (tb_mem_check) atexit(tb_mem_report);\n"; *(const char * *)tb_grow(v_lines) = tb_v4056; }
    { const char * tb_v4057 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4057; }
    { const char * tb_v4058 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4058; }
    { const char * tb_v4059 = "    return tb_mem_check;\n"; *(const char * *)tb_grow(v_lines) = tb_v4059; }
    { const char * tb_v4060 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4060; }
    { const char * tb_v4061 = "static void tb_mem_lock(void) { while (__sync_lock_test_and_set(&tb_mem_spin, 1)) { } }\n"; *(const char * *)tb_grow(v_lines) = tb_v4061; }
    { const char * tb_v4062 = "static void tb_mem_unlock(void) { __sync_lock_release(&tb_mem_spin); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4062; }
    { const char * tb_v4063 = "TB_COLD static void tb_mem_die(int line, const char *what, int at) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4063; }
    { const char * tb_v4064 = "    char buf[200];\n"; *(const char * *)tb_grow(v_lines) = tb_v4064; }
    { const char * tb_v4065 = "    if (at > 0) snprintf(buf, sizeof buf, \"%s (блок из new_mem в строке %d)\", what, at);\n"; *(const char * *)tb_grow(v_lines) = tb_v4065; }
    { const char * tb_v4066 = "    else snprintf(buf, sizeof buf, \"%s\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v4066; }
    { const char * tb_v4067 = "    tb_mem_check = 0;   // программа падает: отчёт о неосвобождённом не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v4067; }
    { const char * tb_v4068 = "    tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4068; }
    { const char * tb_v4069 = "    tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v4069; }
    { const char * tb_v4070 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4070; }
    { const char * tb_v4071 = "TB_API void tb_mem_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4071; }
    { const char * tb_v4072 = "    long long n = 0, bytes = 0; int first = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4072; }
    { const char * tb_v4073 = "    for (long long i = 0; i < tb_mem_n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v4073; }
    { const char * tb_v4074 = "        if (tb_mem_all[i].live) { if (!n) first = tb_mem_all[i].line; n++; bytes += (long long)tb_mem_all[i].n; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4074; }
    { const char * tb_v4075 = "    if (n && tb_mem_check) fprintf(stderr, \"TB_MEM_CHECK: не освобождено блоков %lld (%lld байт), первый из new_mem в строке %d\\n\", n, bytes, first);\n"; *(const char * *)tb_grow(v_lines) = tb_v4075; }
    { const char * tb_v4076 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4076; }
    { const char * tb_v4077 = "// TB_MEM_CHECK: можно ли трогать байты [a, a + n)\n"; *(const char * *)tb_grow(v_lines) = tb_v4077; }
    { const char * tb_v4078 = "static void tb_mem_touch(uintptr_t a, uint64_t n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4078; }
    { const char * tb_v4079 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4079; }
    { const char * tb_v4080 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4080; }
    { const char * tb_v4081 = "    for (long long i = 0; i < tb_mem_n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4081; }
    { const char * tb_v4082 = "        tb_memb *b = &tb_mem_all[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v4082; }
    { const char * tb_v4083 = "        uintptr_t lo = b->a - sizeof(tb_memh), hi = b->a + b->n + TB_MEM_GUARD;\n"; *(const char * *)tb_grow(v_lines) = tb_v4083; }
    { const char * tb_v4084 = "        if (a + n <= lo || a >= hi) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v4084; }
    { const char * tb_v4085 = "        if (!b->live) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4085; }
    { const char * tb_v4086 = "            char buf[160];\n"; *(const char * *)tb_grow(v_lines) = tb_v4086; }
    { const char * tb_v4087 = "            snprintf(buf, sizeof buf, \"эта память уже освобождена: free_mem в строке %d\", b->fline);\n"; *(const char * *)tb_grow(v_lines) = tb_v4087; }
    { const char * tb_v4088 = "            tb_mem_die(line, buf, b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4088; }
    { const char * tb_v4089 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4089; }
    { const char * tb_v4090 = "        if (a < b->a || a + n > b->a + b->n) tb_mem_die(line, \"чтение или запись за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4090; }
    { const char * tb_v4091 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4091; }
    { const char * tb_v4092 = "    tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4092; }
    { const char * tb_v4093 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4093; }
    { const char * tb_v4094 = "static tb_memb *tb_mem_find(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4094; }
    { const char * tb_v4095 = "    for (long long i = tb_mem_n - 1; i >= 0; i--) if (tb_mem_all[i].a == a) return &tb_mem_all[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v4095; }
    { const char * tb_v4096 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4096; }
    { const char * tb_v4097 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4097; }
    { const char * tb_v4098 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v4098; }
    { const char * tb_v4099 = "#define TB_TOUCH(a, n) if (TB_RARE(tb_memchk())) tb_mem_touch((uintptr_t)(a), (n), line)\n"; *(const char * *)tb_grow(v_lines) = tb_v4099; }
    { const char * tb_v4100 = "TB_INL long long tb_rd8(long long a, int line) { TB_TOUCH(a, 1); return *(volatile uint8_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4100; }
    { const char * tb_v4101 = "TB_INL long long tb_rd16(long long a, int line) { TB_TOUCH(a, 2); return *(volatile uint16_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4101; }
    { const char * tb_v4102 = "TB_INL long long tb_rd32(long long a, int line) { TB_TOUCH(a, 4); return *(volatile uint32_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4102; }
    { const char * tb_v4103 = "TB_INL long long tb_rd64(long long a, int line) { TB_TOUCH(a, 8); return (long long)*(volatile uint64_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4103; }
    { const char * tb_v4104 = "TB_INL void tb_wr8(long long a, long long v, int line) { TB_TOUCH(a, 1); *(volatile uint8_t *)(uintptr_t)a = (uint8_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4104; }
    { const char * tb_v4105 = "TB_INL void tb_wr16(long long a, long long v, int line) { TB_TOUCH(a, 2); *(volatile uint16_t *)(uintptr_t)a = (uint16_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4105; }
    { const char * tb_v4106 = "TB_INL void tb_wr32(long long a, long long v, int line) { TB_TOUCH(a, 4); *(volatile uint32_t *)(uintptr_t)a = (uint32_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4106; }
    { const char * tb_v4107 = "TB_INL void tb_wr64(long long a, long long v, int line) { TB_TOUCH(a, 8); *(volatile uint64_t *)(uintptr_t)a = (uint64_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4107; }
    { const char * tb_v4108 = "TB_INL long long tb_addr_of(tb_list *l) { return (long long)(uintptr_t)l->data; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4108; }
    { const char * tb_v4109 = "// new_mem(байт): новый блок, заполнен нулями; адрес — число. Может не получиться (нет памяти)\n"; *(const char * *)tb_grow(v_lines) = tb_v4109; }
    { const char * tb_v4110 = "TB_API long long tb_new_mem(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4110; }
    { const char * tb_v4111 = "    if (n <= 0) { tb_err = \"new_mem: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4111; }
    { const char * tb_v4112 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"new_mem: слишком большой блок\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4112; }
    { const char * tb_v4113 = "    int chk = tb_memchk();\n"; *(const char * *)tb_grow(v_lines) = tb_v4113; }
    { const char * tb_v4114 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4114; }
    { const char * tb_v4115 = "    tb_mem_soft(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4115; }
    { const char * tb_v4116 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4116; }
    { const char * tb_v4117 = "    tb_memh *h = malloc(sizeof(tb_memh) + (size_t)n + (chk ? TB_MEM_GUARD : 0));\n"; *(const char * *)tb_grow(v_lines) = tb_v4117; }
    { const char * tb_v4118 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4118; }
    { const char * tb_v4119 = "    tb_mem_soft(-1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4119; }
    { const char * tb_v4120 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4120; }
    { const char * tb_v4121 = "    if (!h) { tb_err = \"new_mem: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4121; }
    { const char * tb_v4122 = "    h->size = (uint64_t)n; h->magic = TB_MEM_LIVE;\n"; *(const char * *)tb_grow(v_lines) = tb_v4122; }
    { const char * tb_v4123 = "    unsigned char *p = (unsigned char *)(h + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4123; }
    { const char * tb_v4124 = "    memset(p, 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v4124; }
    { const char * tb_v4125 = "    if (chk) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4125; }
    { const char * tb_v4126 = "        memset(p + n, 0xFB, TB_MEM_GUARD);\n"; *(const char * *)tb_grow(v_lines) = tb_v4126; }
    { const char * tb_v4127 = "        tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4127; }
    { const char * tb_v4128 = "        if (tb_mem_n == tb_mem_cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4128; }
    { const char * tb_v4129 = "            long long nc = tb_mem_cap ? tb_mem_cap * 2 : 256;\n"; *(const char * *)tb_grow(v_lines) = tb_v4129; }
    { const char * tb_v4130 = "            tb_memb *all = realloc(tb_mem_all, (size_t)nc * sizeof(tb_memb));\n"; *(const char * *)tb_grow(v_lines) = tb_v4130; }
    { const char * tb_v4131 = "            if (!all) tb_mem_die(line, \"не хватило памяти\", 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4131; }
    { const char * tb_v4132 = "            tb_mem_all = all; tb_mem_cap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v4132; }
    { const char * tb_v4133 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4133; }
    { const char * tb_v4134 = "        tb_memb b = { (uintptr_t)p, (uint64_t)n, 1, line, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4134; }
    { const char * tb_v4135 = "        tb_mem_all[tb_mem_n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v4135; }
    { const char * tb_v4136 = "        tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4136; }
    { const char * tb_v4137 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4137; }
    { const char * tb_v4138 = "    return (long long)(uintptr_t)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4138; }
    { const char * tb_v4139 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4139; }
    { const char * tb_v4140 = "// проверить адрес для free_mem / grow_mem; вернуть заголовок блока\n"; *(const char * *)tb_grow(v_lines) = tb_v4140; }
    { const char * tb_v4141 = "static tb_memh *tb_mem_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4141; }
    { const char * tb_v4142 = "    char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v4142; }
