    { const char * tb_v4149 = "            tb_mem_die(line, buf, b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4149; }
    { const char * tb_v4150 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4150; }
    { const char * tb_v4151 = "        const unsigned char *g = (const unsigned char *)(uintptr_t)a + b->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4151; }
    { const char * tb_v4152 = "        for (int i = 0; i < TB_MEM_GUARD; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v4152; }
    { const char * tb_v4153 = "            if (g[i] != 0xFB) tb_mem_die(line, \"кто-то писал за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4153; }
    { const char * tb_v4154 = "        tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4154; }
