    { const char * tb_v4179 = "// grow_mem(адрес, байт): блок нового размера (данные сохраняются, новое место — нули); адрес может стать другим\n"; *(const char * *)tb_grow(v_lines) = tb_v4179; }
    { const char * tb_v4180 = "TB_API long long tb_grow_mem(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4180; }
    { const char * tb_v4181 = "    if (a == 0) return tb_new_mem(n, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4181; }
    { const char * tb_v4182 = "    if (n <= 0) { tb_err = \"grow_mem: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4182; }
    { const char * tb_v4183 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"grow_mem: слишком большой блок\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4183; }
    { const char * tb_v4184 = "    tb_memh *h = tb_mem_own(a, line, \"grow_mem\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4184; }
    { const char * tb_v4185 = "    uint64_t old = h->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v4185; }
    { const char * tb_v4186 = "    if (tb_memchk()) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4186; }
    { const char * tb_v4187 = "        long long b = tb_new_mem(n, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4187; }
    { const char * tb_v4188 = "        if (!b) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4188; }
    { const char * tb_v4189 = "        memcpy((void *)(uintptr_t)b, (void *)(uintptr_t)a, (size_t)(old < (uint64_t)n ? old : (uint64_t)n));\n"; *(const char * *)tb_grow(v_lines) = tb_v4189; }
    { const char * tb_v4190 = "        tb_mem_bury(a, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4190; }
    { const char * tb_v4191 = "        return b;\n"; *(const char * *)tb_grow(v_lines) = tb_v4191; }
    { const char * tb_v4192 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4192; }
    { const char * tb_v4193 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4193; }
    { const char * tb_v4194 = "    tb_mem_soft(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4194; }
    { const char * tb_v4195 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4195; }
    { const char * tb_v4196 = "    tb_memh *q = realloc(h, sizeof(tb_memh) + (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v4196; }
    { const char * tb_v4197 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4197; }
    { const char * tb_v4198 = "    tb_mem_soft(-1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4198; }
    { const char * tb_v4199 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4199; }
    { const char * tb_v4200 = "    if (!q) { tb_err = \"grow_mem: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4200; }
    { const char * tb_v4201 = "    if ((uint64_t)n > old) memset((unsigned char *)(q + 1) + old, 0, (size_t)((uint64_t)n - old));\n"; *(const char * *)tb_grow(v_lines) = tb_v4201; }
    { const char * tb_v4202 = "    q->size = (uint64_t)n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4202; }
    { const char * tb_v4203 = "    return (long long)(uintptr_t)(q + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4203; }
    { const char * tb_v4204 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4204; }
    { const char * tb_v4205 = "// copy_mem(куда, откуда, байт): блоки могут перекрываться\n"; *(const char * *)tb_grow(v_lines) = tb_v4205; }
    { const char * tb_v4206 = "TB_API void tb_copy_mem(long long dst, long long src, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4206; }
    { const char * tb_v4207 = "    if (n < 0) tb_crash(line, \"copy_mem: число байт меньше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4207; }
    { const char * tb_v4208 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4208; }
    { const char * tb_v4209 = "    if (tb_memchk()) { tb_mem_touch((uintptr_t)src, (uint64_t)n, line); tb_mem_touch((uintptr_t)dst, (uint64_t)n, line); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4209; }
    { const char * tb_v4210 = "    memmove((void *)(uintptr_t)dst, (const void *)(uintptr_t)src, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v4210; }
    { const char * tb_v4211 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4211; }
    { const char * tb_v4212 = "// ---------- use c: функции из C ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4212; }
    { const char * tb_v4213 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v4213; }
    { const char * tb_v4214 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v4214; }
    { const char * tb_v4215 = "#define TB_CSYM(s) __asm__(\"_\" s)\n"; *(const char * *)tb_grow(v_lines) = tb_v4215; }
    { const char * tb_v4216 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4216; }
    { const char * tb_v4217 = "#define TB_CSYM(s) __asm__(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v4217; }
    { const char * tb_v4218 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4218; }
    { const char * tb_v4219 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v4219; }
    { const char * tb_v4220 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4220; }
    { const char * tb_v4221 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v4221; }
    { const char * tb_v4222 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v4222; }
    { const char * tb_v4223 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4223; }
    { const char * tb_v4224 = "    memcpy(s, p, n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4224; }
    { const char * tb_v4225 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4225; }
    { const char * tb_v4226 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4226; }
    { const char * tb_v4227 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v4227; }
    { const char * tb_v4228 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4228; }
    { const char * tb_v4229 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v4229; }
    { const char * tb_v4230 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v4230; }
    { const char * tb_v4231 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v4231; }
    { const char * tb_v4232 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v4232; }
    { const char * tb_v4233 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v4233; }
    { const char * tb_v4234 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v4234; }
    { const char * tb_v4235 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v4235; }
    { const char * tb_v4236 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4236; }
    { const char * tb_v4237 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v4237; }
    { const char * tb_v4238 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4238; }
    { const char * tb_v4239 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4239; }
    { const char * tb_v4240 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v4240; }
    { const char * tb_v4241 = "    return k;\n"; *(const char * *)tb_grow(v_lines) = tb_v4241; }
    { const char * tb_v4242 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4242; }
    { const char * tb_v4243 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v4243; }
    { const char * tb_v4244 = "TB_API long long tb_zone_new(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4244; }
    { const char * tb_v4245 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v4245; }
    { const char * tb_v4246 = "    if (n <= 0) { tb_err = \"zone_new: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4246; }
    { const char * tb_v4247 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"zone_new: слишком большой размер\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4247; }
    { const char * tb_v4248 = "    tb_zone *z = malloc(sizeof(tb_zone));\n"; *(const char * *)tb_grow(v_lines) = tb_v4248; }
    { const char * tb_v4249 = "    if (!z) { tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4249; }
    { const char * tb_v4250 = "    uint64_t step = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v4250; }
    { const char * tb_v4251 = "    z->first = z->cur = tb_zone_chunk(step);\n"; *(const char * *)tb_grow(v_lines) = tb_v4251; }
    { const char * tb_v4252 = "    if (!z->first) { free(z); tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4252; }
    { const char * tb_v4253 = "    z->magic = TB_ZONE_LIVE; z->step = step;\n"; *(const char * *)tb_grow(v_lines) = tb_v4253; }
    { const char * tb_v4254 = "    return (long long)(uintptr_t)z;\n"; *(const char * *)tb_grow(v_lines) = tb_v4254; }
    { const char * tb_v4255 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4255; }
    { const char * tb_v4256 = "static tb_zone *tb_zone_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4256; }
    { const char * tb_v4257 = "    tb_zone *z = (tb_zone *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v4257; }
    { const char * tb_v4258 = "    if (!z || z->magic != TB_ZONE_LIVE) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4258; }
    { const char * tb_v4259 = "        char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v4259; }
    { const char * tb_v4260 = "        snprintf(buf, sizeof buf, \"%s: это не зона из zone_new или она уже освобождена\", who);\n"; *(const char * *)tb_grow(v_lines) = tb_v4260; }
    { const char * tb_v4261 = "        tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v4261; }
    { const char * tb_v4262 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4262; }
    { const char * tb_v4263 = "    return z;\n"; *(const char * *)tb_grow(v_lines) = tb_v4263; }
    { const char * tb_v4264 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4264; }
    { const char * tb_v4265 = "// zone_take(зона, байт): адрес нового куска (нули)\n"; *(const char * *)tb_grow(v_lines) = tb_v4265; }
    { const char * tb_v4266 = "TB_API long long tb_zone_take(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4266; }
    { const char * tb_v4267 = "    tb_zone *z = tb_zone_own(a, line, \"zone_take\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4267; }
    { const char * tb_v4268 = "    if (n <= 0) tb_crash(line, \"zone_take: размер должен быть больше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4268; }
    { const char * tb_v4269 = "    uint64_t need = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v4269; }
    { const char * tb_v4270 = "    tb_zchunk *k = z->cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v4270; }
    { const char * tb_v4271 = "    if (k->size - k->used < need) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4271; }
    { const char * tb_v4272 = "        if (k->next && k->next->size >= need) k = k->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v4272; }
    { const char * tb_v4273 = "        else {\n"; *(const char * *)tb_grow(v_lines) = tb_v4273; }
    { const char * tb_v4274 = "            tb_zchunk *nk = tb_zone_chunk(need > z->step ? need : z->step);\n"; *(const char * *)tb_grow(v_lines) = tb_v4274; }
    { const char * tb_v4275 = "            if (!nk) tb_crash(line, \"zone_take: не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4275; }
    { const char * tb_v4276 = "            nk->next = k->next; k->next = nk; k = nk;\n"; *(const char * *)tb_grow(v_lines) = tb_v4276; }
    { const char * tb_v4277 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4277; }
    { const char * tb_v4278 = "        z->cur = k;\n"; *(const char * *)tb_grow(v_lines) = tb_v4278; }
    { const char * tb_v4279 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4279; }
    { const char * tb_v4280 = "    unsigned char *p = TB_ZDATA(k) + k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v4280; }
    { const char * tb_v4281 = "    k->used += need;\n"; *(const char * *)tb_grow(v_lines) = tb_v4281; }
    { const char * tb_v4282 = "    return (long long)(uintptr_t)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4282; }
    { const char * tb_v4283 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4283; }
    { const char * tb_v4284 = "// zone_clear(зона): всё взятое больше не нужно; первый кусок остаётся для новых zone_take\n"; *(const char * *)tb_grow(v_lines) = tb_v4284; }
    { const char * tb_v4285 = "TB_API void tb_zone_clear(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4285; }
    { const char * tb_v4286 = "    tb_zone *z = tb_zone_own(a, line, \"zone_clear\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4286; }
    { const char * tb_v4287 = "    tb_zchunk *k = z->first->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v4287; }
    { const char * tb_v4288 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4288; }
    { const char * tb_v4289 = "    z->first->next = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4289; }
    { const char * tb_v4290 = "    memset(TB_ZDATA(z->first), 0, (size_t)z->first->used);\n"; *(const char * *)tb_grow(v_lines) = tb_v4290; }
    { const char * tb_v4291 = "    z->first->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4291; }
