    { const char * tb_v4786 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4786; }
    { const char * tb_v4787 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4787; }
