    { const char * tb_v4831 = "        if (type == 0) {   // без сжатия\n"; *(const char * *)tb_grow(v_lines) = tb_v4831; }
    { const char * tb_v4832 = "            z->bits >>= z->nb & 7; z->nb -= z->nb & 7;\n"; *(const char * *)tb_grow(v_lines) = tb_v4832; }
    { const char * tb_v4833 = "            unsigned len = tb_zbits(z, 16), nlen = tb_zbits(z, 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v4833; }
    { const char * tb_v4834 = "            if ((len ^ 0xFFFF) != nlen) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4834; }
    { const char * tb_v4835 = "            while (len-- && !z->err) tb_zput(z, (unsigned char)tb_zbits(z, 8));\n"; *(const char * *)tb_grow(v_lines) = tb_v4835; }
    { const char * tb_v4836 = "        } else if (type == 1 || type == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4836; }
    { const char * tb_v4837 = "            tb_huff lh, dh;\n"; *(const char * *)tb_grow(v_lines) = tb_v4837; }
