    { const char * tb_v4850 = "                for (int i = 0; i < nc; i++) cl[order[i]] = (unsigned char)tb_zbits(z, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v4850; }
    { const char * tb_v4851 = "                tb_huff ch; tb_hbuild(&ch, cl, 19);\n"; *(const char * *)tb_grow(v_lines) = tb_v4851; }
