    { const char * tb_v4856 = "                    if (s == 16) { if (!i) return 0; val = lens[i - 1]; rep = 3 + (int)tb_zbits(z, 2); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4856; }
    { const char * tb_v4857 = "                    else if (s == 17) rep = 3 + (int)tb_zbits(z, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v4857; }
    { const char * tb_v4858 = "                    else if (s == 18) rep = 11 + (int)tb_zbits(z, 7);\n"; *(const char * *)tb_grow(v_lines) = tb_v4858; }
