    { const char * tb_v5477 = "        int y0 = (int)(y * sh / h), y1 = (int)((y + 1) * sh / h);\n"; *(const char * *)tb_grow(v_lines) = tb_v5477; }
    { const char * tb_v5478 = "        if (y1 <= y0) y1 = y0 + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5478; }
    { const char * tb_v5479 = "        for (long long x = 0; x < w; x++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5479; }
    { const char * tb_v5480 = "            int x0 = (int)(x * sw / w), x1 = (int)((x + 1) * sw / w);\n"; *(const char * *)tb_grow(v_lines) = tb_v5480; }
    { const char * tb_v5481 = "            if (x1 <= x0) x1 = x0 + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5481; }
    { const char * tb_v5482 = "            unsigned long long a = 0, r = 0, g = 0, b = 0, n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5482; }
    { const char * tb_v5483 = "            for (int yy = y0; yy < y1; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5483; }
    { const char * tb_v5484 = "                for (int xx = x0; xx < x1; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5484; }
    { const char * tb_v5485 = "                    uint32_t c = src[(size_t)yy * sw + xx];\n"; *(const char * *)tb_grow(v_lines) = tb_v5485; }
    { const char * tb_v5486 = "                    a += c >> 24; r += c >> 16 & 255; g += c >> 8 & 255; b += c & 255; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5486; }
    { const char * tb_v5487 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v5487; }
    { const char * tb_v5488 = "            dst[(size_t)y * w + x] = (uint32_t)(a / n) << 24 | (uint32_t)(r / n) << 16 | (uint32_t)(g / n) << 8 | (uint32_t)(b / n);\n"; *(const char * *)tb_grow(v_lines) = tb_v5488; }
