    { const char * tb_v5506 = "    tb_imgs[tb_nimg].w = tb_gw; tb_imgs[tb_nimg].h = tb_gh; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5506; }
