    { const char * tb_v5982 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5982; }
    { const char * tb_v5983 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5983; }
    { const char * tb_v5984 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5984; }
    { const char * tb_v5985 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v5985; }
    { const char * tb_v5986 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5986; }
    { const char * tb_v5987 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v5987; }
    { const char * tb_v5988 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5988; }
    { const char * tb_v5989 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5989; }
    { const char * tb_v5990 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v5990; }
    { const char * tb_v5991 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5991; }
    { const char * tb_v5992 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5992; }
    { const char * tb_v5993 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v5993; }
    { const char * tb_v5994 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v5994; }
    { const char * tb_v5995 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5995; }
    { const char * tb_v5996 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5996; }
