    { const char * tb_v5998 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5998; }
    { const char * tb_v5999 = "TB_API void tb_gpu_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5999; }
    { const char * tb_v6000 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v6000; }
    { const char * tb_v6001 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6001; }
