    { const char * tb_v6037 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6037; }
    { const char * tb_v6038 = "TB_API void tb_gpu_glyph(long long x, long long y, int g, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6038; }
    { const char * tb_v6039 = "    if (x >= tb_gw || y >= tb_gh || x + 8 * size <= 0 || y + 16 * size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6039; }
    { const char * tb_v6040 = "    if (size >= (1 << 22) || x < -(1LL << 30) || y < -(1LL << 30)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6040; }
