    { const char * tb_v7987 = "TB_API unsigned tb_pci_r(int bus, int dev, int fn, int off) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7987; }
    { const char * tb_v7988 = "    tb_outl(0xCF8, 0x80000000u | (unsigned)bus << 16 | (unsigned)dev << 11 | (unsigned)fn << 8 | (unsigned)(off & 0xFC));\n"; *(const char * *)tb_grow(v_lines) = tb_v7988; }
    { const char * tb_v7989 = "    return tb_inl(0xCFC);\n"; *(const char * *)tb_grow(v_lines) = tb_v7989; }
