    { const char * tb_v9189 = "        } else if (e.type == ButtonPress || e.type == ButtonRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9189; }
    { const char * tb_v9190 = "            if (e.xbutton.button == 1) { tb_mdown = e.type == ButtonPress; if (tb_mdown) tb_mtap = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9190; }
    { const char * tb_v9191 = "            if (e.xbutton.button == 8 || e.xbutton.button == 9) tb_side(e.xbutton.button - 8, e.type == ButtonPress);\n"; *(const char * *)tb_grow(v_lines) = tb_v9191; }
    { const char * tb_v9192 = "            if (e.type == ButtonPress && e.xbutton.button == 4) tb_wheel_add(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9192; }
    { const char * tb_v9193 = "            if (e.type == ButtonPress && e.xbutton.button == 5) tb_wheel_add(-1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9193; }
    { const char * tb_v9194 = "            tb_mx = e.xbutton.x; tb_my = e.xbutton.y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9194; }
    { const char * tb_v9195 = "        } else if (e.type == MotionNotify) { tb_mx = e.xmotion.x; tb_my = e.xmotion.y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9195; }
    { const char * tb_v9196 = "        else if (e.type == ConfigureNotify && (e.xconfigure.width != tb_gw || e.xconfigure.height != tb_gh)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9196; }
    { const char * tb_v9197 = "            tb_new_w = e.xconfigure.width; tb_new_h = e.xconfigure.height;\n"; *(const char * *)tb_grow(v_lines) = tb_v9197; }
    { const char * tb_v9198 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9198; }
    { const char * tb_v9199 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9199; }
    { const char * tb_v9200 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v9200; }
    { const char * tb_v9201 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9201; }
    { const char * tb_v9202 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v9202; }
    { const char * tb_v9203 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v9203; }
    { const char * tb_v9204 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v9204; }
    { const char * tb_v9205 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v9205; }
    { const char * tb_v9206 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v9206; }
    { const char * tb_v9207 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v9207; }
    { const char * tb_v9208 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9208; }
    { const char * tb_v9209 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9209; }
    { const char * tb_v9210 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v9210; }
    { const char * tb_v9211 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9211; }
    { const char * tb_v9212 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9212; }
    { const char * tb_v9213 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v9213; }
    { const char * tb_v9214 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9214; }
    { const char * tb_v9215 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v9215; }
    { const char * tb_v9216 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v9216; }
    { const char * tb_v9217 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v9217; }
    { const char * tb_v9218 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9218; }
    { const char * tb_v9219 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9219; }
    { const char * tb_v9220 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v9220; }
    { const char * tb_v9221 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v9221; }
    { const char * tb_v9222 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v9222; }
    { const char * tb_v9223 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9223; }
    { const char * tb_v9224 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9224; }
    { const char * tb_v9225 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9225; }
    { const char * tb_v9226 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9226; }
    { const char * tb_v9227 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9227; }
    { const char * tb_v9228 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v9228; }
    { const char * tb_v9229 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9229; }
    { const char * tb_v9230 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v9230; }
    { const char * tb_v9231 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v9231; }
    { const char * tb_v9232 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9232; }
    { const char * tb_v9233 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9233; }
    { const char * tb_v9234 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9234; }
    { const char * tb_v9235 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9235; }
    { const char * tb_v9236 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9236; }
    { const char * tb_v9237 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9237; }
    { const char * tb_v9238 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9238; }
    { const char * tb_v9239 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9239; }
    { const char * tb_v9240 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9240; }
    { const char * tb_v9241 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9241; }
    { const char * tb_v9242 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9242; }
    { const char * tb_v9243 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9243; }
    { const char * tb_v9244 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9244; }
    { const char * tb_v9245 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v9245; }
    { const char * tb_v9246 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9246; }
    { const char * tb_v9247 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v9247; }
    { const char * tb_v9248 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v9248; }
    { const char * tb_v9249 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9249; }
    { const char * tb_v9250 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9250; }
    { const char * tb_v9251 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9251; }
    { const char * tb_v9252 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9252; }
    { const char * tb_v9253 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v9253; }
    { const char * tb_v9254 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9254; }
    { const char * tb_v9255 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v9255; }
    { const char * tb_v9256 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9256; }
    { const char * tb_v9257 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9257; }
    { const char * tb_v9258 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v9258; }
    { const char * tb_v9259 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v9259; }
    { const char * tb_v9260 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v9260; }
    { const char * tb_v9261 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9261; }
    { const char * tb_v9262 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9262; }
    { const char * tb_v9263 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9263; }
    { const char * tb_v9264 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9264; }
    { const char * tb_v9265 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9265; }
    { const char * tb_v9266 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9266; }
    { const char * tb_v9267 = "        tb_sc = tb_gfx_scale();\n"; *(const char * *)tb_grow(v_lines) = tb_v9267; }
    { const char * tb_v9268 = "        if (tb_sc < 1) tb_sc = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9268; }
    { const char * tb_v9269 = "        if (tb_sc > 4) tb_sc = 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v9269; }
    { const char * tb_v9270 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9270; }
    { const char * tb_v9271 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v9271; }
    { const char * tb_v9272 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v9272; }
    { const char * tb_v9273 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9273; }
    { const char * tb_v9274 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9274; }
    { const char * tb_v9275 = "    tb_px = calloc((size_t)tb_gw * tb_gh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9275; }
    { const char * tb_v9276 = "    if (!tb_gfx_open(title)) { free(tb_px); tb_px = 0; tb_err = \"не могу открыть окно: нет экрана\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9276; }
    { const char * tb_v9277 = "    if (tb_gpu_on && tb_gpu_check) { atexit(tb_gpu_report); tb_gpu_blend_probe(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9277; }
    { const char * tb_v9278 = "    tb_last_frame = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v9278; }
    { const char * tb_v9279 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9279; }
    { const char * tb_v9280 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v9280; }
    { const char * tb_v9281 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v9281; }
    { const char * tb_v9282 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9282; }
    { const char * tb_v9283 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9283; }
    { const char * tb_v9284 = "    int nw = tb_new_w > 8192 ? 8192 : tb_new_w, nh = tb_new_h > 8192 ? 8192 : tb_new_h, ow = tb_gw, oh = tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9284; }
    { const char * tb_v9285 = "    tb_new_w = tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9285; }
    { const char * tb_v9286 = "    if (nw < 1 || nh < 1 || (nw == ow && nh == oh)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9286; }
    { const char * tb_v9287 = "    uint32_t *np = calloc((size_t)nw * nh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9287; }
    { const char * tb_v9288 = "    if (!np) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9288; }
    { const char * tb_v9289 = "    for (int y = 0; y < oh && y < nh; y++) memcpy(np + (size_t)y * nw, tb_px + (size_t)y * ow, (size_t)(ow < nw ? ow : nw) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9289; }
    { const char * tb_v9290 = "    free(tb_px);\n"; *(const char * *)tb_grow(v_lines) = tb_v9290; }
    { const char * tb_v9291 = "    tb_px = np; tb_gw = nw; tb_gh = nh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9291; }
    { const char * tb_v9292 = "    tb_gfx_reimage();\n"; *(const char * *)tb_grow(v_lines) = tb_v9292; }
    { const char * tb_v9293 = "    if (tb_gpu_on && !tb_gpu_resize(ow, oh)) fprintf(stderr, \"видеокарта: не получилось поменять размер кадра\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v9293; }
    { const char * tb_v9294 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9294; }
    { const char * tb_v9295 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9295; }
    { const char * tb_v9296 = "TB_API long long tb_window_h(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gh; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9296; }
    { const char * tb_v9297 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v9297; }
    { const char * tb_v9298 = "TB_API double tb_frame_ms_v = 16.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9298; }
    { const char * tb_v9299 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9299; }
    { const char * tb_v9300 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9300; }
    { const char * tb_v9301 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9301; }
    { const char * tb_v9302 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9302; }
    { const char * tb_v9303 = "    int nosync = n == 0 || getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9303; }
    { const char * tb_v9304 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9304; }
    { const char * tb_v9305 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9305; }
    { const char * tb_v9306 = "TB_API double tb_frame_ms(void) { return tb_frame_ms_v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9306; }
    { const char * tb_v9307 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9307; }
    { const char * tb_v9308 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v9308; }
    { const char * tb_v9309 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9309; }
    { const char * tb_v9310 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9310; }
    { const char * tb_v9311 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v9311; }
    { const char * tb_v9312 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v9312; }
    { const char * tb_v9313 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v9313; }
    { const char * tb_v9314 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v9314; }
    { const char * tb_v9315 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9315; }
    { const char * tb_v9316 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9316; }
    { const char * tb_v9317 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9317; }
    { const char * tb_v9318 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v9318; }
    { const char * tb_v9319 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9319; }
    { const char * tb_v9320 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v9320; }
    { const char * tb_v9321 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v9321; }
