    { const char * tb_v9349 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v9349; }
    { const char * tb_v9350 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9350; }
