    { const char * tb_v9377 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9377; }
    { const char * tb_v9378 = "// draw_shadow(x, y, w, h, r, size, c): мягкая тень скруглённого прямоугольника — внутри цвет c,\n"; *(const char * *)tb_grow(v_lines) = tb_v9378; }
    { const char * tb_v9379 = "// снаружи к size точкам сходит на нет. Корень считается только у кольца и углов, середина — простое смешивание.\n"; *(const char * *)tb_grow(v_lines) = tb_v9379; }
    { const char * tb_v9380 = "TB_API void tb_draw_shadow(long long x, long long y, long long w, long long h, long long r, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9380; }
    { const char * tb_v9381 = "    if (!tb_px || w <= 0 || h <= 0 || size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9381; }
    { const char * tb_v9382 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9382; }
