    { const char * tb_v9386 = "            double f = 1.0 - (double)k / size;\n"; *(const char * *)tb_grow(v_lines) = tb_v9386; }
    { const char * tb_v9387 = "            long long a = (long long)((255 - ((c >> 24) & 255)) * f * f / (size / 2.0) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9387; }
    { const char * tb_v9388 = "            if (a > 0) tb_gpu_rect(x - k, y - k + r, w + 2 * k, h + 2 * k - 2 * r, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v9388; }
    { const char * tb_v9389 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9389; }
    { const char * tb_v9390 = "        if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9390; }
    { const char * tb_v9391 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9391; }
    { const char * tb_v9392 = "    double hw = w / 2.0, hh = h / 2.0, cx = x + hw, cy = y + hh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9392; }
    { const char * tb_v9393 = "    long long y0 = y - size < 0 ? 0 : y - size, y1 = y + h + size > tb_gh ? tb_gh : y + h + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v9393; }
    { const char * tb_v9394 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9394; }
