    { const char * tb_v9406 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9406; }
    { const char * tb_v9407 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9407; }
    { const char * tb_v9408 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9408; }
    { const char * tb_v9409 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v9409; }
    { const char * tb_v9410 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9410; }
    { const char * tb_v9411 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v9411; }
    { const char * tb_v9412 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9412; }
    { const char * tb_v9413 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v9413; }
    { const char * tb_v9414 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v9414; }
    { const char * tb_v9415 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9415; }
    { const char * tb_v9416 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9416; }
    { const char * tb_v9417 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v9417; }
    { const char * tb_v9418 = "        while (*e && *e != ' ' && *e != ',') e++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9418; }
    { const char * tb_v9419 = "        for (int i = 0; i < 9; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9419; }
    { const char * tb_v9420 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9420; }
    { const char * tb_v9421 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v9421; }
    { const char * tb_v9422 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9422; }
    { const char * tb_v9423 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v9423; }
    { const char * tb_v9424 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9424; }
    { const char * tb_v9425 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba)\n"; *(const char * *)tb_grow(v_lines) = tb_v9425; }
    { const char * tb_v9426 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9426; }
    { const char * tb_v9427 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9427; }
    { const char * tb_v9428 = "    int m = tb_corners(corners);\n"; *(const char * *)tb_grow(v_lines) = tb_v9428; }
    { const char * tb_v9429 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9429; }
    { const char * tb_v9430 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9430; }
    { const char * tb_v9431 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9431; }
    { const char * tb_v9432 = "    if (tb_gpu_on) {   // видеокарта: пока без сглаживания\n"; *(const char * *)tb_grow(v_lines) = tb_v9432; }
    { const char * tb_v9433 = "        tb_gpu_rect(x + r, y, w - 2 * r, h, c); tb_gpu_rect(x, y + r, r, h - 2 * r, c); tb_gpu_rect(x + w - r, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9433; }
    { const char * tb_v9434 = "        tb_gpu_circle(x + r, y + r, r, c); tb_gpu_circle(x + w - 1 - r, y + r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9434; }
    { const char * tb_v9435 = "        tb_gpu_circle(x + r, y + h - 1 - r, r, c); tb_gpu_circle(x + w - 1 - r, y + h - 1 - r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9435; }
    { const char * tb_v9436 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9436; }
    { const char * tb_v9437 = "    if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9437; }
    { const char * tb_v9438 = "    uint32_t cc = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v9438; }
    { const char * tb_v9439 = "    long long y0 = y < 0 ? 0 : y, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9439; }
    { const char * tb_v9440 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9440; }
    { const char * tb_v9441 = "        long long row = j - y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9441; }
    { const char * tb_v9442 = "        int top = row < r, bot = row >= h - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9442; }
    { const char * tb_v9443 = "        int lc = (top && (m & 1)) || (bot && (m & 4)), rc = (top && (m & 2)) || (bot && (m & 8));\n"; *(const char * *)tb_grow(v_lines) = tb_v9443; }
    { const char * tb_v9444 = "        double cy = top ? y + r - 0.5 : y + h - r - 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v9444; }
    { const char * tb_v9445 = "        // середина строки — сплошняком\n"; *(const char * *)tb_grow(v_lines) = tb_v9445; }
    { const char * tb_v9446 = "        long long a = x + (lc ? r : 0), b = x + w - (rc ? r : 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9446; }
    { const char * tb_v9447 = "        if (a < 0) a = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9447; }
    { const char * tb_v9448 = "        if (b > tb_gw) b = tb_gw;\n"; *(const char * *)tb_grow(v_lines) = tb_v9448; }
    { const char * tb_v9449 = "        if ((cc >> 24) & 255) { for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], cc); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9449; }
    { const char * tb_v9450 = "        else for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = cc & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v9450; }
    { const char * tb_v9451 = "        // углы: покрытие точки по расстоянию до центра угла\n"; *(const char * *)tb_grow(v_lines) = tb_v9451; }
    { const char * tb_v9452 = "        for (int side = 0; side < 2; side++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9452; }
    { const char * tb_v9453 = "            if (!(side ? rc : lc)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v9453; }
    { const char * tb_v9454 = "            double cx = side ? x + w - r - 0.5 : x + r - 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v9454; }
    { const char * tb_v9455 = "            long long i0 = side ? x + w - r : x, i1 = side ? x + w : x + r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9455; }
    { const char * tb_v9456 = "            for (long long i = i0; i < i1; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9456; }
    { const char * tb_v9457 = "                double dx = i + 0.5 - (cx + 0.5), dy = j + 0.5 - (cy + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9457; }
    { const char * tb_v9458 = "                double d = sqrt(dx * dx + dy * dy);\n"; *(const char * *)tb_grow(v_lines) = tb_v9458; }
    { const char * tb_v9459 = "                tb_cover(i, j, cc, r - d + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9459; }
