    { const char * tb_v9463 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9463; }
    { const char * tb_v9464 = "// размыть то, что уже нарисовано в прямоугольнике (матовое стекло, мягкий фон): три прохода «ящиком»\n"; *(const char * *)tb_grow(v_lines) = tb_v9464; }
    { const char * tb_v9465 = "// размытие одного ряда (n точек с шагом step в буфере b) скользящей суммой окна 2r+1; tmp — n точек\n"; *(const char * *)tb_grow(v_lines) = tb_v9465; }
    { const char * tb_v9466 = "TB_INL void tb_blur_run(uint32_t *b, long long n, long long step, long long r, uint32_t *tmp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9466; }
    { const char * tb_v9467 = "    for (long long k = 0; k < n; k++) tmp[k] = b[k * step];\n"; *(const char * *)tb_grow(v_lines) = tb_v9467; }
    { const char * tb_v9468 = "    long long win = 2 * r + 1, sr = 0, sg = 0, sb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9468; }
    { const char * tb_v9469 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v9469; }
    { const char * tb_v9470 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9470; }
    { const char * tb_v9471 = "        uint32_t v = tmp[k < 0 ? 0 : k >= n ? n - 1 : k];\n"; *(const char * *)tb_grow(v_lines) = tb_v9471; }
    { const char * tb_v9472 = "        sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9472; }
    { const char * tb_v9473 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9473; }
    { const char * tb_v9474 = "    for (long long k = 0; k < n; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9474; }
    { const char * tb_v9475 = "        uint64_t vr = ((uint64_t)sr * mul + (1u << 23)) >> 24, vg = ((uint64_t)sg * mul + (1u << 23)) >> 24, vb = ((uint64_t)sb * mul + (1u << 23)) >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v9475; }
    { const char * tb_v9476 = "        b[k * step] = (uint32_t)((vr > 255 ? 255 : vr) << 16 | (vg > 255 ? 255 : vg) << 8 | (vb > 255 ? 255 : vb));\n"; *(const char * *)tb_grow(v_lines) = tb_v9476; }
    { const char * tb_v9477 = "        uint32_t out = tmp[k - r < 0 ? 0 : k - r], in = tmp[k + r + 1 >= n ? n - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9477; }
    { const char * tb_v9478 = "        sr += (long long)((in >> 16) & 255) - ((out >> 16) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9478; }
    { const char * tb_v9479 = "        sg += (long long)((in >> 8) & 255) - ((out >> 8) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9479; }
    { const char * tb_v9480 = "        sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9480; }
    { const char * tb_v9481 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9481; }
    { const char * tb_v9482 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9482; }
    { const char * tb_v9483 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v9483; }
    { const char * tb_v9484 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v9484; }
    { const char * tb_v9485 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9485; }
    { const char * tb_v9486 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9486; }
    { const char * tb_v9487 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9487; }
    { const char * tb_v9488 = "    long long W = x1 - x0, H = y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9488; }
    { const char * tb_v9489 = "    if (W <= 1 || H <= 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9489; }
    { const char * tb_v9490 = "    int half = r >= 4 && W >= 8 && H >= 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9490; }
    { const char * tb_v9491 = "    long long bw = half ? (W + 1) / 2 : W, bh = half ? (H + 1) / 2 : H, br = half ? r / 2 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9491; }
    { const char * tb_v9492 = "    uint32_t *b = malloc((size_t)(bw * bh + (bw > bh ? bw : bh)) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9492; }
    { const char * tb_v9493 = "    if (!b) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9493; }
    { const char * tb_v9494 = "    uint32_t *tmp = b + bw * bh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9494; }
    { const char * tb_v9495 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v9495; }
    { const char * tb_v9496 = "        for (long long yy = 0; yy < bh; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9496; }
    { const char * tb_v9497 = "            for (long long xx = 0; xx < bw; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9497; }
    { const char * tb_v9498 = "                long long sx = x0 + xx * 2, sy = y0 + yy * 2, sx2 = sx + 1 < x1 ? sx + 1 : sx, sy2 = sy + 1 < y1 ? sy + 1 : sy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9498; }
    { const char * tb_v9499 = "                uint32_t p = tb_px[sy * tb_gw + sx], q = tb_px[sy * tb_gw + sx2], u = tb_px[sy2 * tb_gw + sx], v = tb_px[sy2 * tb_gw + sx2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9499; }
    { const char * tb_v9500 = "                b[yy * bw + xx] = (((p >> 16 & 255) + (q >> 16 & 255) + (u >> 16 & 255) + (v >> 16 & 255) + 2) / 4) << 16\n"; *(const char * *)tb_grow(v_lines) = tb_v9500; }
    { const char * tb_v9501 = "                    | (((p >> 8 & 255) + (q >> 8 & 255) + (u >> 8 & 255) + (v >> 8 & 255) + 2) / 4) << 8\n"; *(const char * *)tb_grow(v_lines) = tb_v9501; }
    { const char * tb_v9502 = "                    | (((p & 255) + (q & 255) + (u & 255) + (v & 255) + 2) / 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9502; }
    { const char * tb_v9503 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9503; }
    { const char * tb_v9504 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v9504; }
    { const char * tb_v9505 = "        for (long long yy = 0; yy < bh; yy++) memcpy(b + yy * bw, tb_px + (y0 + yy) * tb_gw + x0, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9505; }
    { const char * tb_v9506 = "    for (int pass = 0; pass < 3; pass++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9506; }
    { const char * tb_v9507 = "        for (long long yy = 0; yy < bh; yy++) tb_blur_run(b + yy * bw, bw, 1, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v9507; }
    { const char * tb_v9508 = "        for (long long xx = 0; xx < bw; xx++) tb_blur_run(b + xx, bh, bw, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v9508; }
    { const char * tb_v9509 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9509; }
    { const char * tb_v9510 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v9510; }
    { const char * tb_v9511 = "        // обратно: каждая точка — смесь четырёх соседних из маленькой картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v9511; }
    { const char * tb_v9512 = "        for (long long yy = 0; yy < H; yy++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9512; }
    { const char * tb_v9513 = "            long long fy = yy * 128 - 64; if (fy < 0) fy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9513; }
    { const char * tb_v9514 = "            long long iy = fy >> 8, ty = fy & 255, iy2 = iy + 1 < bh ? iy + 1 : iy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9514; }
    { const char * tb_v9515 = "            for (long long xx = 0; xx < W; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9515; }
    { const char * tb_v9516 = "                long long fx = xx * 128 - 64; if (fx < 0) fx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9516; }
    { const char * tb_v9517 = "                long long ix = fx >> 8, tx = fx & 255, ix2 = ix + 1 < bw ? ix + 1 : ix;\n"; *(const char * *)tb_grow(v_lines) = tb_v9517; }
    { const char * tb_v9518 = "                uint32_t p = b[iy * bw + ix], q = b[iy * bw + ix2], u = b[iy2 * bw + ix], v = b[iy2 * bw + ix2], o = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9518; }
    { const char * tb_v9519 = "                for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9519; }
    { const char * tb_v9520 = "                    long long a = (p >> sh & 255) * (256 - tx) + (q >> sh & 255) * tx, c = (u >> sh & 255) * (256 - tx) + (v >> sh & 255) * tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v9520; }
    { const char * tb_v9521 = "                    o |= (uint32_t)(((a * (256 - ty) + c * ty + 32768) >> 16) & 255) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9521; }
    { const char * tb_v9522 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v9522; }
    { const char * tb_v9523 = "                tb_px[(y0 + yy) * tb_gw + x0 + xx] = o;\n"; *(const char * *)tb_grow(v_lines) = tb_v9523; }
    { const char * tb_v9524 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9524; }
    { const char * tb_v9525 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9525; }
    { const char * tb_v9526 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v9526; }
    { const char * tb_v9527 = "        for (long long yy = 0; yy < bh; yy++) memcpy(tb_px + (y0 + yy) * tb_gw + x0, b + yy * bw, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9527; }
    { const char * tb_v9528 = "    free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v9528; }
    { const char * tb_v9529 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9529; }
    { const char * tb_v9530 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9530; }
    { const char * tb_v9531 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9531; }
    { const char * tb_v9532 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9532; }
    { const char * tb_v9533 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v9533; }
    { const char * tb_v9534 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9534; }
    { const char * tb_v9535 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v9535; }
    { const char * tb_v9536 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9536; }
    { const char * tb_v9537 = "            if (i * i + j * j <= r * r + r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9537; }
    { const char * tb_v9538 = "                if ((c >> 24) & 255) { uint32_t *p = &tb_px[(cy + j) * tb_gw + cx + i]; *p = tb_mix(*p, (uint32_t)c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9538; }
    { const char * tb_v9539 = "                else tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9539; }
    { const char * tb_v9540 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9540; }
    { const char * tb_v9541 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9541; }
    { const char * tb_v9542 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9542; }
    { const char * tb_v9543 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9543; }
    { const char * tb_v9544 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9544; }
    { const char * tb_v9545 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9545; }
    { const char * tb_v9546 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9546; }
    { const char * tb_v9547 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v9547; }
    { const char * tb_v9548 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9548; }
    { const char * tb_v9549 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v9549; }
    { const char * tb_v9550 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9550; }
    { const char * tb_v9551 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v9551; }
    { const char * tb_v9552 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v9552; }
    { const char * tb_v9553 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9553; }
    { const char * tb_v9554 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9554; }
    { const char * tb_v9555 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9555; }
    { const char * tb_v9556 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9556; }
    { const char * tb_v9557 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v9557; }
    { const char * tb_v9558 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9558; }
    { const char * tb_v9559 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v9559; }
    { const char * tb_v9560 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v9560; }
    { const char * tb_v9561 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v9561; }
    { const char * tb_v9562 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v9562; }
    { const char * tb_v9563 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v9563; }
    { const char * tb_v9564 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9564; }
    { const char * tb_v9565 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v9565; }
    { const char * tb_v9566 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9566; }
    { const char * tb_v9567 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9567; }
    { const char * tb_v9568 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9568; }
    { const char * tb_v9569 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9569; }
    { const char * tb_v9570 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9570; }
    { const char * tb_v9571 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9571; }
    { const char * tb_v9572 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9572; }
    { const char * tb_v9573 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9573; }
    { const char * tb_v9574 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9574; }
    { const char * tb_v9575 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9575; }
    { const char * tb_v9576 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9576; }
    { const char * tb_v9577 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9577; }
    { const char * tb_v9578 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v9578; }
    { const char * tb_v9579 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9579; }
    { const char * tb_v9580 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9580; }
    { const char * tb_v9581 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v9581; }
    { const char * tb_v9582 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v9582; }
