    { const char * tb_v9584 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v9584; }
    { const char * tb_v9585 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v9585; }
    { const char * tb_v9586 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9586; }
    { const char * tb_v9587 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9587; }
    { const char * tb_v9588 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v9588; }
