    { const char * tb_v9590 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9590; }
    { const char * tb_v9591 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v9591; }
