    { const char * tb_v9600 = "    long long su = (tx->cu + tx->au * (2 * x + 1) + tx->bu * (2 * y + 1)) >> 6, sv = (tx->cv + tx->av * (2 * x + 1) + tx->bv * (2 * y + 1)) >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v9600; }
    { const char * tb_v9601 = "    long long u = tb_fdiv(tb_fdiv(su, W), 16), v = tb_fdiv(tb_fdiv(sv, W), 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v9601; }
    { const char * tb_v9602 = "    u -= tb_fdiv(u, tx->w) * (long long)tx->w;   // повтор картинки: 0…w-1\n"; *(const char * *)tb_grow(v_lines) = tb_v9602; }
    { const char * tb_v9603 = "    v -= tb_fdiv(v, tx->h) * (long long)tx->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9603; }
    { const char * tb_v9604 = "    *out = tb_imgpx[tx->off + (uint32_t)v * tx->w + (uint32_t)u];\n"; *(const char * *)tb_grow(v_lines) = tb_v9604; }
    { const char * tb_v9605 = "    return (*out >> 24) >= 128;\n"; *(const char * *)tb_grow(v_lines) = tb_v9605; }
    { const char * tb_v9606 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9606; }
    { const char * tb_v9607 = "// точка картинки × оттенок (свет): (т · о + 127) / 255 по каждому цвету\n"; *(const char * *)tb_grow(v_lines) = tb_v9607; }
    { const char * tb_v9608 = "TB_INL uint32_t tb_tex_tint(uint32_t t, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9608; }
    { const char * tb_v9609 = "    uint32_t r = (((t >> 16) & 255) * ((c >> 16) & 255) + 127) / 255, g = (((t >> 8) & 255) * ((c >> 8) & 255) + 127) / 255,\n"; *(const char * *)tb_grow(v_lines) = tb_v9609; }
