    { const char * tb_v9630 = "            for (long long x = xa; x <= xb; x++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9630; }
    { const char * tb_v9631 = "                if (tb_tri_edge(t[0], t[1], t[2], t[3], x, y) && tb_tri_edge(t[2], t[3], t[4], t[5], x, y) &&\n"; *(const char * *)tb_grow(v_lines) = tb_v9631; }
    { const char * tb_v9632 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9632; }
    { const char * tb_v9633 = "                    uint32_t col = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v9633; }
    { const char * tb_v9634 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v9634; }
    { const char * tb_v9635 = "                        uint32_t d = tb_tri3_depth(pl, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v9635; }
