    { const char * tb_v9637 = "                        if (tx) {   // картинка: прозрачная точка (меньше 128) — дырка, глубину не пишет\n"; *(const char * *)tb_grow(v_lines) = tb_v9637; }
    { const char * tb_v9638 = "                            uint32_t tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v9638; }
