    { const char * tb_v9649 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v9649; }
    { const char * tb_v9650 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v9650; }
    { const char * tb_v9651 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v9651; }
    { const char * tb_v9652 = "// округление до ближайшего целого (половина — вверх); быстрее llround, одно и то же везде\n"; *(const char * *)tb_grow(v_lines) = tb_v9652; }
    { const char * tb_v9653 = "TB_INL long long tb_rnd(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9653; }
    { const char * tb_v9654 = "    long long r = (long long)(x + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9654; }
    { const char * tb_v9655 = "    if ((double)r > x + 0.5) r--;\n"; *(const char * *)tb_grow(v_lines) = tb_v9655; }
    { const char * tb_v9656 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9656; }
    { const char * tb_v9657 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9657; }
    { const char * tb_v9658 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9658; }
    { const char * tb_v9659 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9659; }
    { const char * tb_v9660 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v9660; }
