    { const char * tb_v9662 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v9662; }
    { const char * tb_v9663 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9663; }
    { const char * tb_v9664 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v9664; }
    { const char * tb_v9665 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9665; }
    { const char * tb_v9666 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9666; }
    { const char * tb_v9667 = "            int j = (i + 1) % n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9667; }
    { const char * tb_v9668 = "            double vi = side == 0 ? ax[i] - gx0 : side == 1 ? gx1 - ax[i] : side == 2 ? ay[i] - gy0 : gy1 - ay[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9668; }
    { const char * tb_v9669 = "            double vj = side == 0 ? ax[j] - gx0 : side == 1 ? gx1 - ax[j] : side == 2 ? ay[j] - gy0 : gy1 - ay[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v9669; }
    { const char * tb_v9670 = "            if (vi >= 0) { bx[m] = ax[i]; by[m] = ay[i]; m++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9670; }
    { const char * tb_v9671 = "            if ((vi >= 0) != (vj >= 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9671; }
    { const char * tb_v9672 = "                double k = vi / (vi - vj);\n"; *(const char * *)tb_grow(v_lines) = tb_v9672; }
    { const char * tb_v9673 = "                bx[m] = ax[i] + (ax[j] - ax[i]) * k; by[m] = ay[i] + (ay[j] - ay[i]) * k; m++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9673; }
    { const char * tb_v9674 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9674; }
    { const char * tb_v9675 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9675; }
    { const char * tb_v9676 = "        n = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v9676; }
    { const char * tb_v9677 = "        for (int i = 0; i < n; i++) { ax[i] = bx[i]; ay[i] = by[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9677; }
    { const char * tb_v9678 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9678; }
