    { const char * tb_v9710 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9710; }
    { const char * tb_v9711 = "// то же с настоящей прозрачностью: точка = округл(цвет * a / 255) + округл(фон * (255 - a) / 255).\n"; *(const char * *)tb_grow(v_lines) = tb_v9711; }
    { const char * tb_v9712 = "// Две части округляются порознь: так получается одинаково на любой видеокарте (шейдер считает первую часть сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v9712; }
    { const char * tb_v9713 = "TB_API void tb_draw_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9713; }
    { const char * tb_v9714 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9714; }
    { const char * tb_v9715 = "    if (tb_gpu_on) tb_gpu_image_a(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v9715; }
    { const char * tb_v9716 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9716; }
    { const char * tb_v9717 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v9717; }
    { const char * tb_v9718 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v9718; }
    { const char * tb_v9719 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9719; }
    { const char * tb_v9720 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v9720; }
    { const char * tb_v9721 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9721; }
    { const char * tb_v9722 = "            uint32_t v = src[j * im->w + i], a = v >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v9722; }
    { const char * tb_v9723 = "            if (a == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v9723; }
    { const char * tb_v9724 = "            uint32_t *d = &tb_px[(y + j) * tb_gw + x + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9724; }
    { const char * tb_v9725 = "            if (a == 255) { *d = v & 0xFFFFFF; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9725; }
    { const char * tb_v9726 = "            uint32_t o = *d, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9726; }
    { const char * tb_v9727 = "            for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9727; }
    { const char * tb_v9728 = "                uint32_t sc = (v >> sh) & 255, dc = (o >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9728; }
    { const char * tb_v9729 = "                uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9729; }
    { const char * tb_v9730 = "                r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9730; }
    { const char * tb_v9731 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9731; }
    { const char * tb_v9732 = "            *d = r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9732; }
    { const char * tb_v9733 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9733; }
    { const char * tb_v9734 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9734; }
    { const char * tb_v9735 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9735; }
    { const char * tb_v9736 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v9736; }
    { const char * tb_v9737 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9737; }
    { const char * tb_v9738 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9738; }
    { const char * tb_v9739 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9739; }
    { const char * tb_v9740 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v9740; }
    { const char * tb_v9741 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v9741; }
    { const char * tb_v9742 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9742; }
    { const char * tb_v9743 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9743; }
    { const char * tb_v9744 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v9744; }
    { const char * tb_v9745 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9745; }
    { const char * tb_v9746 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v9746; }
    { const char * tb_v9747 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v9747; }
    { const char * tb_v9748 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9748; }
    { const char * tb_v9749 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v9749; }
    { const char * tb_v9750 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v9750; }
    { const char * tb_v9751 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v9751; }
    { const char * tb_v9752 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9752; }
    { const char * tb_v9753 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9753; }
    { const char * tb_v9754 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v9754; }
    { const char * tb_v9755 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v9755; }
    { const char * tb_v9756 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v9756; }
    { const char * tb_v9757 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v9757; }
    { const char * tb_v9758 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v9758; }
    { const char * tb_v9759 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v9759; }
    { const char * tb_v9760 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v9760; }
    { const char * tb_v9761 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9761; }
    { const char * tb_v9762 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v9762; }
    { const char * tb_v9763 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9763; }
    { const char * tb_v9764 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9764; }
    { const char * tb_v9765 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9765; }
    { const char * tb_v9766 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v9766; }
    { const char * tb_v9767 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9767; }
    { const char * tb_v9768 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9768; }
    { const char * tb_v9769 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v9769; }
    { const char * tb_v9770 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v9770; }
    { const char * tb_v9771 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v9771; }
    { const char * tb_v9772 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v9772; }
    { const char * tb_v9773 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v9773; }
    { const char * tb_v9774 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v9774; }
    { const char * tb_v9775 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v9775; }
    { const char * tb_v9776 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v9776; }
    { const char * tb_v9777 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v9777; }
    { const char * tb_v9778 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v9778; }
    { const char * tb_v9779 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v9779; }
    { const char * tb_v9780 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v9780; }
    { const char * tb_v9781 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v9781; }
    { const char * tb_v9782 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v9782; }
    { const char * tb_v9783 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v9783; }
    { const char * tb_v9784 = "    int32_t *nrm; long long nrmcap; int nrmok;   // нормаль каждого треугольника в сетке (× 2^14), для света\n"; *(const char * *)tb_grow(v_lines) = tb_v9784; }
    { const char * tb_v9785 = "    double *uv; long long tex;   // картинка сетки (mesh_image, -1 — нет) и (u, v) трёх углов треугольника (NAN — без картинки)\n"; *(const char * *)tb_grow(v_lines) = tb_v9785; }
    { const char * tb_v9786 = "    long long nch, *chr; double *chs, bs[4]; int chok; } tb_mesh;   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v9786; }
    { const char * tb_v9787 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9787; }
    { const char * tb_v9788 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9788; }
    { const char * tb_v9789 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v9789; }
    { const char * tb_v9790 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v9790; }
    { const char * tb_v9791 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9791; }
    { const char * tb_v9792 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9792; }
    { const char * tb_v9793 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v9793; }
    { const char * tb_v9794 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v9794; }
    { const char * tb_v9795 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9795; }
    { const char * tb_v9796 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v9796; }
    { const char * tb_v9797 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9797; }
    { const char * tb_v9798 = "    tb_meshes[tb_nmesh].tex = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9798; }
    { const char * tb_v9799 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9799; }
    { const char * tb_v9800 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9800; }
    { const char * tb_v9801 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9801; }
    { const char * tb_v9802 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9802; }
    { const char * tb_v9803 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v9803; }
    { const char * tb_v9804 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9804; }
    { const char * tb_v9805 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9805; }
    { const char * tb_v9806 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9806; }
    { const char * tb_v9807 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v9807; }
    { const char * tb_v9808 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9808; }
    { const char * tb_v9809 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v9809; }
    { const char * tb_v9810 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9810; }
    { const char * tb_v9811 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v9811; }
    { const char * tb_v9812 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v9812; }
    { const char * tb_v9813 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9813; }
    { const char * tb_v9814 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9814; }
    { const char * tb_v9815 = "            uint64_t h = tb_vhash(m->v + 3 * v) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9815; }
    { const char * tb_v9816 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9816; }
    { const char * tb_v9817 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v9817; }
    { const char * tb_v9818 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9818; }
    { const char * tb_v9819 = "        free(m->hk); m->hk = nk; m->hcap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v9819; }
    { const char * tb_v9820 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9820; }
    { const char * tb_v9821 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9821; }
    { const char * tb_v9822 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9822; }
    { const char * tb_v9823 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v9823; }
    { const char * tb_v9824 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9824; }
    { const char * tb_v9825 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9825; }
    { const char * tb_v9826 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9826; }
    { const char * tb_v9827 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v9827; }
    { const char * tb_v9828 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9828; }
    { const char * tb_v9829 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9829; }
    { const char * tb_v9830 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9830; }
    { const char * tb_v9831 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v9831; }
    { const char * tb_v9832 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9832; }
    { const char * tb_v9833 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9833; }
    { const char * tb_v9834 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9834; }
    { const char * tb_v9835 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v9835; }
    { const char * tb_v9836 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v9836; }
    { const char * tb_v9837 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9837; }
    { const char * tb_v9838 = "    m->vi[4 * m->nv + 3] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9838; }
    { const char * tb_v9839 = "    m->hk[h] = m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v9839; }
    { const char * tb_v9840 = "    return (uint32_t)m->nv++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9840; }
    { const char * tb_v9841 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9841; }
    { const char * tb_v9842 = "TB_API void tb_mesh_add(long long id, double x1, double y1, double z1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v9842; }
    { const char * tb_v9843 = "                        double x3, double y3, double z3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9843; }
