    { const char * tb_v9878 = "// картинка для сетки: её треугольники из mesh_add_uv рисуются ею (остальные — своим цветом); -1 — без картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v9878; }
    { const char * tb_v9879 = "TB_API void tb_mesh_image(long long id, long long img) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9879; }
    { const char * tb_v9880 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9880; }
