    { const char * tb_v10429 = "// ---------- геймпад: pad_count(), pad_down(n, \"a\"), pad_axis(n, \"lx\") ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v10429; }
    { const char * tb_v10430 = "// Кнопки: a b x y l1 r1 l2 r2 l3 r3 start select home up down left right.\n"; *(const char * *)tb_grow(v_lines) = tb_v10430; }
    { const char * tb_v10431 = "// Оси (от -1 до 1, курки от 0 до 1): lx ly rx ry l2 r2. Вниз и вправо — плюс. n — номер геймпада с 0.\n"; *(const char * *)tb_grow(v_lines) = tb_v10431; }
    { const char * tb_v10432 = "// Mac — GameController, Windows — XInput, Linux — /dev/input/js*. В ядре без ОС геймпадов нет.\n"; *(const char * *)tb_grow(v_lines) = tb_v10432; }
    { const char * tb_v10433 = "enum { TB_PB_A, TB_PB_B, TB_PB_X, TB_PB_Y, TB_PB_L1, TB_PB_R1, TB_PB_L2, TB_PB_R2, TB_PB_L3, TB_PB_R3,\n"; *(const char * *)tb_grow(v_lines) = tb_v10433; }
