    { const char * tb_v10438 = "TB_API tb_pad tb_pads[TB_PADS];\n"; *(const char * *)tb_grow(v_lines) = tb_v10438; }
    { const char * tb_v10439 = "TB_API long long tb_pad_t = -1000;   // когда опрашивали (мс): не чаще раза в 4 мс\n"; *(const char * *)tb_grow(v_lines) = tb_v10439; }
    { const char * tb_v10440 = "#if defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v10440; }
