    { const char * tb_v10444 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10444; }
    { const char * tb_v10445 = "    if (!tried) { tried = 1; dlopen(\"/System/Library/Frameworks/GameController.framework/GameController\", RTLD_LAZY); }\n"; *(const char * *)tb_grow(v_lines) = tb_v10445; }
    { const char * tb_v10446 = "    id cls = TB_CLS(\"GCController\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10446; }
