    { const char * tb_v10458 = "            \"leftTrigger\", \"rightTrigger\", \"leftThumbstickButton\", \"rightThumbstickButton\", \"buttonMenu\", \"buttonOptions\", \"buttonHome\", 0, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v10458; }
    { const char * tb_v10459 = "        for (int k = 0; k < TB_PB_N; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10459; }
