    { const char * tb_v10614 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v10614; }
    { const char * tb_v10615 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v10615; }
    { const char * tb_v10616 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v10616; }
    { const char * tb_v10617 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v10617; }
    { const char * tb_v10618 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v10618; }
    { const char * tb_v10619 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v10619; }
    { const char * tb_v10620 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v10620; }
    { const char * tb_v10621 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v10621; }
    { const char * tb_v10622 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v10622; }
    { const char * tb_v10623 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v10623; }
    { const char * tb_v10624 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v10624; }
    { const char * tb_v10625 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v10625; }
    { const char * tb_v10626 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v10626; }
    { const char * tb_v10627 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v10627; }
    { const char * tb_v10628 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v10628; }
    { const char * tb_v10629 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v10629; }
    { const char * tb_v10630 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v10630; }
    { const char * tb_v10631 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v10631; }
    { const char * tb_v10632 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v10632; }
    { const char * tb_v10633 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v10633; }
    { const char * tb_v10634 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v10634; }
    { const char * tb_v10635 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v10635; }
    { const char * tb_v10636 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v10636; }
    { const char * tb_v10637 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v10637; }
    { const char * tb_v10638 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v10638; }
    { const char * tb_v10639 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v10639; }
    { const char * tb_v10640 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v10640; }
    { const char * tb_v10641 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v10641; }
    { const char * tb_v10642 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v10642; }
    { const char * tb_v10643 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v10643; }
    { const char * tb_v10644 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v10644; }
    { const char * tb_v10645 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10645; }
    { const char * tb_v10646 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10646; }
    { const char * tb_v10647 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v10647; }
    { const char * tb_v10648 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v10648; }
    { const char * tb_v10649 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10649; }
    { const char * tb_v10650 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10650; }
    { const char * tb_v10651 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10651; }
    { const char * tb_v10652 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10652; }
    { const char * tb_v10653 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10653; }
    { const char * tb_v10654 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10654; }
    { const char * tb_v10655 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v10655; }
    { const char * tb_v10656 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10656; }
    { const char * tb_v10657 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v10657; }
    { const char * tb_v10658 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10658; }
    { const char * tb_v10659 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v10659; }
    { const char * tb_v10660 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v10660; }
    { const char * tb_v10661 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v10661; }
    { const char * tb_v10662 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v10662; }
    { const char * tb_v10663 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v10663; }
    { const char * tb_v10664 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v10664; }
    { const char * tb_v10665 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10665; }
    { const char * tb_v10666 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10666; }
    { const char * tb_v10667 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v10667; }
    { const char * tb_v10668 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v10668; }
    { const char * tb_v10669 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10669; }
    { const char * tb_v10670 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v10670; }
    { const char * tb_v10671 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10671; }
    { const char * tb_v10672 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10672; }
    { const char * tb_v10673 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v10673; }
    { const char * tb_v10674 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10674; }
    { const char * tb_v10675 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10675; }
    { const char * tb_v10676 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v10676; }
    { const char * tb_v10677 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10677; }
    { const char * tb_v10678 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v10678; }
    { const char * tb_v10679 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v10679; }
    { const char * tb_v10680 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10680; }
    { const char * tb_v10681 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10681; }
    { const char * tb_v10682 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v10682; }
    { const char * tb_v10683 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v10683; }
    { const char * tb_v10684 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10684; }
    { const char * tb_v10685 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v10685; }
    { const char * tb_v10686 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v10686; }
    { const char * tb_v10687 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v10687; }
    { const char * tb_v10688 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v10688; }
    { const char * tb_v10689 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v10689; }
    { const char * tb_v10690 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v10690; }
    { const char * tb_v10691 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10691; }
    { const char * tb_v10692 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10692; }
    { const char * tb_v10693 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v10693; }
    { const char * tb_v10694 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v10694; }
    { const char * tb_v10695 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v10695; }
    { const char * tb_v10696 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v10696; }
    { const char * tb_v10697 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v10697; }
    { const char * tb_v10698 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v10698; }
    { const char * tb_v10699 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v10699; }
    { const char * tb_v10700 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10700; }
    { const char * tb_v10701 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10701; }
    { const char * tb_v10702 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v10702; }
    { const char * tb_v10703 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v10703; }
    { const char * tb_v10704 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v10704; }
    { const char * tb_v10705 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v10705; }
    { const char * tb_v10706 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10706; }
    { const char * tb_v10707 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v10707; }
    { const char * tb_v10708 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v10708; }
    { const char * tb_v10709 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10709; }
    { const char * tb_v10710 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v10710; }
    { const char * tb_v10711 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10711; }
    { const char * tb_v10712 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v10712; }
    { const char * tb_v10713 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v10713; }
    { const char * tb_v10714 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10714; }
    { const char * tb_v10715 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v10715; }
    { const char * tb_v10716 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v10716; }
    { const char * tb_v10717 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v10717; }
    { const char * tb_v10718 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10718; }
    { const char * tb_v10719 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10719; }
    { const char * tb_v10720 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10720; }
    { const char * tb_v10721 = "        if (v->is3d) tb_voice_3d(v, &tl, &tr, &tdl, &tdr, &al, &ar);\n"; *(const char * *)tb_grow(v_lines) = tb_v10721; }
    { const char * tb_v10722 = "        if (v->stop) { tl = 0; tr = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10722; }
    { const char * tb_v10723 = "        if (v->fresh) { v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr; v->fresh = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10723; }
    { const char * tb_v10724 = "        double step = s->rate / TB_SR * v->pitch * (v->is3d ? v->dop : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10724; }
    { const char * tb_v10725 = "        float gl = v->gl, gr = v->gr, dgl = (tl - gl) / n, dgr = (tr - gr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10725; }
    { const char * tb_v10726 = "        double dl = v->dl, dr = v->dr, ddl = (tdl - dl) / n, ddr = (tdr - dr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10726; }
    { const char * tb_v10727 = "        int done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10727; }
    { const char * tb_v10728 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10728; }
    { const char * tb_v10729 = "            float l, r;\n"; *(const char * *)tb_grow(v_lines) = tb_v10729; }
    { const char * tb_v10730 = "            if (v->is3d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10730; }
    { const char * tb_v10731 = "                l = tb_smono(s, v->pos - dl * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v10731; }
    { const char * tb_v10732 = "                r = tb_smono(s, v->pos - dr * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v10732; }
    { const char * tb_v10733 = "                v->lpl += al * (l - v->lpl);\n"; *(const char * *)tb_grow(v_lines) = tb_v10733; }
    { const char * tb_v10734 = "                v->lpr += ar * (r - v->lpr);\n"; *(const char * *)tb_grow(v_lines) = tb_v10734; }
    { const char * tb_v10735 = "                l = v->lpl;\n"; *(const char * *)tb_grow(v_lines) = tb_v10735; }
    { const char * tb_v10736 = "                r = v->lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v10736; }
    { const char * tb_v10737 = "            } else if (s->ch > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10737; }
    { const char * tb_v10738 = "                l = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v10738; }
    { const char * tb_v10739 = "                r = tb_sread(s, v->pos, 1, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v10739; }
    { const char * tb_v10740 = "            } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v10740; }
    { const char * tb_v10741 = "                l = r = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v10741; }
    { const char * tb_v10742 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v10742; }
    { const char * tb_v10743 = "            out[2 * i] += l * gl;\n"; *(const char * *)tb_grow(v_lines) = tb_v10743; }
    { const char * tb_v10744 = "            out[2 * i + 1] += r * gr;\n"; *(const char * *)tb_grow(v_lines) = tb_v10744; }
    { const char * tb_v10745 = "            gl += dgl; gr += dgr; dl += ddl; dr += ddr;\n"; *(const char * *)tb_grow(v_lines) = tb_v10745; }
    { const char * tb_v10746 = "            v->pos += step;\n"; *(const char * *)tb_grow(v_lines) = tb_v10746; }
    { const char * tb_v10747 = "            if (v->pos >= (double)s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10747; }
    { const char * tb_v10748 = "                if (v->loop) v->pos -= (double)s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10748; }
    { const char * tb_v10749 = "                else { done = 1; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10749; }
    { const char * tb_v10750 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v10750; }
    { const char * tb_v10751 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10751; }
    { const char * tb_v10752 = "        v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr;\n"; *(const char * *)tb_grow(v_lines) = tb_v10752; }
    { const char * tb_v10753 = "        if (done || v->stop) tb_voice_end(v);\n"; *(const char * *)tb_grow(v_lines) = tb_v10753; }
    { const char * tb_v10754 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10754; }
