    { const char * tb_v11048 = "// тон: синус hz герц на ms миллисекунд, мягкое начало и конец (без щелчков)\n"; *(const char * *)tb_grow(v_lines) = tb_v11048; }
    { const char * tb_v11049 = "TB_API long long tb_play_tone(double hz, long long ms) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11049; }
    { const char * tb_v11050 = "    if (ms <= 0 || hz <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11050; }
    { const char * tb_v11051 = "    if (ms > 60000) ms = 60000;\n"; *(const char * *)tb_grow(v_lines) = tb_v11051; }
    { const char * tb_v11052 = "    long long n = ms * TB_SR / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v11052; }
    { const char * tb_v11053 = "    float *d = malloc(sizeof(float) * (size_t)(n + 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v11053; }
    { const char * tb_v11054 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11054; }
    { const char * tb_v11055 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v11055; }
    { const char * tb_v11056 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v11056; }
    { const char * tb_v11057 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11057; }
    { const char * tb_v11058 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11058; }
    { const char * tb_v11059 = "        if (i < ramp) e = (double)i / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v11059; }
    { const char * tb_v11060 = "        else if (i >= n - ramp) e = (double)(n - 1 - i) / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v11060; }
    { const char * tb_v11061 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v11061; }
    { const char * tb_v11062 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11062; }
    { const char * tb_v11063 = "    long long s = tb_snd_add(d, n, 1, TB_SR, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v11063; }
    { const char * tb_v11064 = "    if (s < 0) { free(d); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11064; }
    { const char * tb_v11065 = "    long long v = tb_voice_new(s, 0, 0, 0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v11065; }
